$r="D:\openVela\contest2026_043_CircuitForge"
foreach ($f in "$r\app\velapaw\infer\model\velapaw.tflite","$r\app\velapaw\infer\model\bcs.tflite","$r\nuttx.bin") {
  $i=Get-Item $f; "{0,-16} {1,9} bytes  md5 {2}" -f $i.Name, $i.Length, (Get-FileHash $f -Algorithm MD5).Hash
}

$bytes=[IO.File]::ReadAllBytes("D:\openVela\contest2026_043_CircuitForge\nuttx.bin")
$txt=[Text.Encoding]::GetEncoding(28591).GetString($bytes)
foreach ($p in 'skipped','waiting for pet','pending','ate %','%02d:%02d') {
  $c=[regex]::Matches($txt,[regex]::Escape($p)).Count
  "{0,-18} {1} hits" -f $p,$c
}
"--- UTF-8 CJK probes ---"
$u8=[Text.Encoding]::UTF8
foreach ($s in '已跳过','待投喂','未到时间') {
  $pat=($u8.GetBytes($s) | ForEach-Object { [char]$_ }) -join ''
  "{0} -> {1} hits" -f $s, [regex]::Matches($txt,[regex]::Escape($pat)).Count
}

$bytes=[IO.File]::ReadAllBytes("D:\openVela\contest2026_043_CircuitForge\nuttx.bin")
$txt=[Text.Encoding]::GetEncoding(28591).GetString($bytes)
"--- exact i18n literals ---"
foreach ($p in '  %02d:%02d   skipped','  %02d:%02d   pending','  %02d:%02d   waiting for pet') {
  "{0,-34} {1} hits" -f $p, [regex]::Matches($txt,[regex]::Escape($p)).Count
}
"--- context around 'skipped' ---"
$i=$txt.IndexOf('skipped'); if($i -ge 0){ ($txt.Substring([Math]::Max(0,$i-160),300) -replace '[^\x20-\x7E]','.') }
"--- CJK method check ---"
$u8=[Text.Encoding]::UTF8
foreach ($s in '宠物','喂食','跳过','投喂') {
  $pat=($u8.GetBytes($s)|ForEach-Object{[char]$_}) -join ''
  "{0} -> {1} hits" -f $s,[regex]::Matches($txt,[regex]::Escape($pat)).Count
}

foreach ($p in 'D:\openVela\apps\examples\velapaw','D:\openVela\velapaw-snapshots','D:\openVela\spi-lcd-lab') {
  if (Test-Path $p) { "FOUND $p"; Get-ChildItem $p | Select-Object -First 12 Name,LastWriteTime | Format-Table -AutoSize | Out-String } else { "missing: $p" }
}

$bytes=[IO.File]::ReadAllBytes("D:\openVela\contest2026_043_CircuitForge\nuttx.bin")
$txt=[Text.Encoding]::GetEncoding(28591).GetString($bytes)
$src=Get-Content "D:\openVela\contest2026_043_CircuitForge\app\velapaw\ui\ui_i18n.c" -Raw
$miss=@(); $tot=0
foreach ($m in [regex]::Matches($src,'\{\s*"((?:[^"\\]|\\.)*)"\s*,')) {
  $s=$m.Groups[1].Value -replace '\\n',"`n" -replace '\\"','"'
  if ($s.Length -lt 4) { continue }
  $tot++
  if (-not $txt.Contains($s)) { $miss += $s }
}
"checked $tot English strings; missing from firmware: $($miss.Count)"
$miss | ForEach-Object { "  MISSING: $_" }

