```bash
ls /dev/ttyUSB* /dev/ttyACM* 2>/dev/null
esptool.py --chip esp32s3 --port /dev/ttyUSB0 --baud 921600 write_flash 0x0 ~/openvela/nuttx/nuttx.bin
