     static void vp_sync_day(void)
     {
       long today = vp_today_num();
       if (today < 0)        { return; }          /* clock unusable */
       if (g_hist_day < 0)   { g_hist_day = today; vp_history_save(); return; }
       if (today <= g_hist_day) { return; }       /* same day, or backwards */
       vp_shift_days((int)(today - g_hist_day));
       g_hist_day = today;
       vp_history_save();
     }

     int velapaw_store_init(void)
     {
       memset(g_day_g, 0, sizeof(g_day_g));
       memset(g_day_m, 0, sizeof(g_day_m));
       for (int i = 0; i < VELAPAW_MAX_PETS; i++) { g_bcs[i] = -1; }
       vp_history_load();
       vp_sync_day();
       /* Write the digest at startup too.  Without this, status.md does not exist
        * until the next feed, enroll or BCS update ... */
       vp_status_write();
       return 0;
     }
     ```
