```bash
cd ~/openvela
cat > /tmp/velapaw-utf8.py <<'PYEOF'
import os

P = os.path.expanduser('~/openvela/packages/ai_agent/src/core/agent_loop.c')

with open(P, encoding='utf-8', errors='surrogateescape') as f:
    s = f.read()

if 'utf8_valid_prefix' in s:
    print('SKIP  (already applied)')
    raise SystemExit(0)

HELPERS = r'''/* DeepSeek rejects the ENTIRE request with
 *   HTTP 400 ... messages[N].content: invalid unicode code point
 * when any message content holds a malformed UTF-8 sequence.  Text cut at a
 * byte boundary mid-character does exactly that, and because the cut text is
 * kept in history it poisons every later turn too.  It hurts most right after
 * a SUCCESSFUL mutating tool call: the write is already on flash, so the owner
 * is told "Sorry, I encountered an error" about an action that worked
 * (velapaw set_meal_schedule, 2026-10-11).
 *
 * Returns the length of the longest well-formed UTF-8 prefix of s.  Reading
 * p[i + k] can never run past the terminator: a NUL fails the continuation
 * test and stops the scan.
 */

static size_t utf8_valid_prefix(const char* s)
{
    const unsigned char* p = (const unsigned char*)s;
    size_t i = 0;

    while (p[i]) {
        unsigned char c = p[i];
        int need;

        if (c < 0x80) {
            i++;
            continue;
        } else if ((c & 0xE0) == 0xC0) {
            need = 1;
        } else if ((c & 0xF0) == 0xE0) {
            need = 2;
        } else if ((c & 0xF8) == 0xF0) {
            need = 3;
        } else {
            break;      /* stray continuation byte, or 0xF8..0xFF */
        }

        for (int k = 1; k <= need; k++) {
            if ((p[i + k] & 0xC0) != 0x80) {
                return i;
            }
        }
        i += need + 1;
    }

    return i;
}

/* Attach a string that is guaranteed to be well-formed UTF-8.  The common
 * case costs nothing: a clean string is handed straight to cJSON with no
 * copy.  Only a malformed one is duplicated and truncated. */

static void add_clean_string(cJSON* obj, const char* key, const char* val)
{
    if (val == NULL) {
        cJSON_AddNullToObject(obj, key);
        return;
    }

    size_t full = strlen(val);
    size_t valid = utf8_valid_prefix(val);

    if (valid == full) {
        cJSON_AddStringToObject(obj, key, val);
        return;
    }

    syslog(LOG_WARNING,
        "[%s] UTF-8: trimmed %d of %d byte(s) from \"%s\"\n",
        TAG, (int)(full - valid), (int)full, key);

    char* tmp = malloc(valid + 1);
    if (tmp) {
        memcpy(tmp, val, valid);
        tmp[valid] = '\0';
        cJSON_AddStringToObject(obj, key, tmp);
        free(tmp);
    } else {
        cJSON_AddStringToObject(obj, key, "");
    }
}

'''

DIAG = r'''
    /* DIAGNOSTIC (velapaw 2026-10-11): the 400 names an index, so print the
     * array with per-message UTF-8 validity and pin the bad message to a real
     * role instead of inferring it from the message count.  Runs before this
     * round's tool result is appended, so it covers system/skills/user/
     * assistant -- the sites that cannot be reached from the add paths. */
    {
        int idx = 0;
        cJSON* m = NULL;
        cJSON_ArrayForEach(m, messages) {
            cJSON* role = cJSON_GetObjectItem(m, "role");
            cJSON* content = cJSON_GetObjectItem(m, "content");
            const char* cs = cJSON_IsString(content)
                ? content->valuestring : NULL;
            size_t full = cs ? strlen(cs) : 0;
            size_t ok = cs ? utf8_valid_prefix(cs) : 0;

            syslog(LOG_INFO, "[%s] msg[%d] role=%s len=%d utf8ok=%d%s\n",
                TAG, idx++,
                cJSON_IsString(role) ? role->valuestring : "?",
                (int)full, (int)ok,
                (full == ok) ? "" : "  <== MALFORMED");
        }
    }
'''

EDITS = [
    # 1. helpers, before the first function that needs them
    ('static void add_assistant_message(cJSON* messages, '
     'const llm_response_t* resp)',
     HELPERS + 'static void add_assistant_message(cJSON* messages, '
     'const llm_response_t* resp)'),

    # 2. assistant reply text
    ('        cJSON_AddStringToObject(asst_msg, "content", resp->text);',
     '        add_clean_string(asst_msg, "content", resp->text);'),

    # 3. Kimi reasoning echo
    ('        cJSON_AddStringToObject(asst_msg, "reasoning_content",\n'
     '            resp->reasoning_content);',
     '        add_clean_string(asst_msg, "reasoning_content",\n'
     '            resp->reasoning_content);'),

    # 4. array dump
    ('    const char* msg_chat_id)\n{\n    int n = resp->call_count;',
     '    const char* msg_chat_id)\n{\n    int n = resp->call_count;\n'
     + DIAG),

    # 5. single-tool result
    ('        cJSON_AddStringToObject(result_msg, "content", tool_output);',
     '        add_clean_string(result_msg, "content", tool_output);'),

    # 6. parallel-tool result
    ('            cJSON_AddStringToObject(result_msg, "content",\n'
     '                (tasks[i].output && tasks[i].output[0])\n'
     '                    ? tasks[i].output\n'
     '                    : "{}");',
     '            add_clean_string(result_msg, "content",\n'
     '                (tasks[i].output && tasks[i].output[0])\n'
     '                    ? tasks[i].output\n'
     '                    : "{}");'),
]

for i, (anchor, new) in enumerate(EDITS, 1):
    if s.count(anchor) != 1:
        print('FAIL  edit %d: anchor x%d' % (i, s.count(anchor)))
        raise SystemExit(1)
    s = s.replace(anchor, new)
    print('ok    edit %d' % i)

with open(P, 'w', encoding='utf-8', errors='surrogateescape') as f:
    f.write(s)
print('PATCH src/core/agent_loop.c')
PYEOF
python3 /tmp/velapaw-utf8.py
