704	/* Capture one VSYNC-aligned frame into g_cambuf (internal). */
705	static void cam_capture_once(void)
706	{
707	  /* start camera streaming */
708	  creg(R_CAM_CTRL1, B_CAM_START);
709	  sreg(R_CAM_CTRL1, B_CAM_RESET); creg(R_CAM_CTRL1, B_CAM_RESET);
710	  sreg(R_CAM_CTRL, B_CAM_UPDATE);
711	  sreg(R_CAM_CTRL1, B_CAM_START);
712	  /* align to frame start, then arm the DMA -> one clean aligned frame */
713	  cam_wait_vsync();
714	  sreg(R_CAM_CTRL1, B_CAM_AFIFO_RST); creg(R_CAM_CTRL1, B_CAM_AFIFO_RST);
715	  wreg(R_CAM_INT_CLR, ~0u);
716	  esp32s3_dma_disable(g_camchan, false);   /* clean state before re-arm */
717	  esp32s3_dma_load(g_camdesc, g_camchan, false);
718	  esp32s3_dma_enable(g_camchan, false);
719	  /* wait for the frame-end VSYNC so we read a COMPLETE, single frame (a fixed
720	   * delay races the frame time and gives torn/half frames when the scene moves) */
721	  cam_wait_vsync();
722	  up_mdelay(2);    /* let the DMA flush the frame tail from the AFIFO to PSRAM */
723	  cache_invalidate_addr((uint32_t)(uintptr_t)g_cambuf, CAM_FRAME_BYTES);
