727	   * the descriptor/AFIFO state after ~N frames and wedges the whole SoC
728	   * (seen as a console "semaphore timeout"). Stop the RX DMA and halt camera
729	   * streaming after every frame; the next capture re-arms cleanly. */
730	  esp32s3_dma_disable(g_camchan, false);
731	  creg(R_CAM_CTRL1, B_CAM_START);   /* clear START -> stop streaming */
