732	/****************************************************************************
733	 * Name: i2s_rxdma_start
734	 *
735	 * Description:
736	 *   Initiate the next RX DMA transfer. Assuming the DMA inlink is already
737	 *   bound, it's safe to start the next DMA transfer in an interrupt context.
738	 *
739	 * Input Parameters:
740	 *   priv - Initialized I2S device structure.
741	 *
742	 * Returned Value:
743	 *   OK on success; a negated errno value on failure
744	 *
745	 * Assumptions:
746	 *   Interrupts are disabled
747	 *
748	 ****************************************************************************/
749	
750	#ifdef I2S_HAVE_RX
751	static int i2s_rxdma_start(struct esp32s3_i2s_s *priv)
752	{
753	  struct esp32s3_buffer_s *bfcontainer;
754	  size_t eof_nbytes;
755	
756	  /* If there is already an active transmission in progress, then bail
757	   * returning success.
758	   */
759	
760	  if (!sq_empty(&priv->rx.act))
761	    {
762	      return OK;
763	    }
764	
765	  /* If there are no pending transfer, then bail returning success */
766	
767	  if (sq_empty(&priv->rx.pend))
768	    {
769	      return OK;
770	    }
771	
772	  bfcontainer = (struct esp32s3_buffer_s *)sq_remfirst(&priv->rx.pend);
773	
774	  /* If there isn't already an active transmission in progress,
775	   * then start it.
776	   */
777	
778	  eof_nbytes = MIN(bfcontainer->nbytes, ESP32S3_DMA_BUFLEN_MAX);
779	
780	  modifyreg32(I2S_RXEOF_NUM_REG(priv->config->port), I2S_RX_EOF_NUM_M,
781	              FIELD_TO_VALUE(I2S_RX_EOF_NUM, eof_nbytes));
782	
783	  esp32s3_dma_load(bfcontainer->dma_link, priv->dma_channel, I2S_RX);
784	  esp32s3_dma_enable(priv->dma_channel, I2S_RX);
785	
786	  modifyreg32(I2S_RX_CONF_REG(priv->config->port), 0, I2S_RX_START);
787	
788	  sq_addlast((sq_entry_t *)bfcontainer, &priv->rx.act);
789	
790	  return OK;
791	}
792	#endif /* I2S_HAVE_RX */
