794	/****************************************************************************
795	 * Name: i2s_txdma_setup
796	 *
797	 * Description:
798	 *   Setup the next TX DMA transfer
799	 *
800	 * Input Parameters:
801	 *   priv - Initialized I2S device structure.
802	 *   bfcontainer - The buffer container to be set up
803	 *
804	 * Returned Value:
805	 *   OK on success; a negated errno value on failure
806	 *
807	 * Assumptions:
808	 *   Interrupts are disabled
809	 *
810	 ****************************************************************************/
811	
812	#ifdef I2S_HAVE_TX
813	static IRAM_ATTR int i2s_txdma_setup(struct esp32s3_i2s_s *priv,
814	                                     struct esp32s3_buffer_s *bfcontainer)
815	{
816	  int ret = OK;
817	  size_t carry_size;
818	  uint32_t bytes_queued;
819	  uint32_t data_copied;
820	  struct ap_buffer_s *apb;
821	  struct esp32s3_dmadesc_s *outlink;
822	  apb_samp_t samp_size;
823	  irqstate_t flags;
824	  uint8_t *buf;
825	  uint8_t padding;
826	  uint8_t *samp;
827	
828	  DEBUGASSERT(bfcontainer && bfcontainer->apb);
829	
830	  apb = bfcontainer->apb;
831	  outlink = bfcontainer->dma_link;
832	
833	  /* Get the transfer information, accounting for any data offset */
834	
835	  const apb_samp_t bytes_per_sample = priv->data_width / 8;
836	  samp = &apb->samp[apb->curbyte];
837	  samp_size = (apb->nbytes - apb->curbyte) + priv->tx.carry.bytes;
838	  carry_size = samp_size % bytes_per_sample;
839	
840	  /* Allocate the current audio buffer considering the remaining bytes
841	   * carried from the last upper half audio buffer.
842	   */
843	
844	  bfcontainer->buf = calloc(bfcontainer->nbytes, 1);
845	  if (bfcontainer->buf == NULL)
846	    {
847	      i2serr("Failed to allocate the DMA internal buffer "
848	             "[%" PRIu32 " bytes]", bfcontainer->nbytes);
849	      return -ENOMEM;
850	    }
851	
852	  data_copied = 0;
853	  buf = bfcontainer->buf;
854	
855	  /* Copy the remaining bytes from the last audio buffer to the current
856	   * audio buffer. The remaining bytes are part of a sample that was split
857	   * between the last and the current audio buffer. Also, copy the bytes
858	   * from that split sample that are on the current buffer to the internal
859	   * buffer.
860	   */
861	
862	  if (priv->tx.carry.bytes)
863	    {
864	      memcpy(buf, &priv->tx.carry.value, priv->tx.carry.bytes);
865	      buf += priv->tx.carry.bytes;
866	      data_copied += priv->tx.carry.bytes;
867	      memcpy(buf, samp, (bytes_per_sample - priv->tx.carry.bytes));
868	      buf += (bytes_per_sample - priv->tx.carry.bytes);
869	      samp += (bytes_per_sample - priv->tx.carry.bytes);
870	      data_copied += (bytes_per_sample - priv->tx.carry.bytes);
871	    }
872	
873	  /* Copy the upper half buffer to the internal buffer considering that
874	   * the current upper half buffer may not contain a complete sample at
875	   * the end of the buffer (and those bytes needs to be carried to the
876	   * next audio buffer).
877	   */
878	
879	  memcpy(buf, samp, samp_size - (data_copied + carry_size));
880	  buf += samp_size - (data_copied + carry_size);
881	  samp += samp_size - (data_copied + carry_size);
882	  data_copied += samp_size - (data_copied + carry_size);
883	
884	  /* If the audio buffer's size is not a multiple of the sample size,
885	   * it's necessary to carry the remaining bytes that are part of what
886	   * would be the last sample on this buffer. These bytes will then be
887	   * saved and inserted at the beginning of the next DMA buffer to
888	   * rebuild the sample correctly.
889	   */
890	
891	  priv->tx.carry.bytes = carry_size;
892	
893	  if (priv->tx.carry.bytes)
894	    {
895	      memcpy((uint8_t *)&priv->tx.carry.value, samp, priv->tx.carry.bytes);
896	    }
897	
898	  /* Release our reference on the audio buffer. This may very likely
899	   * cause the audio buffer to be freed.
900	   */
901	
902	  apb_free(bfcontainer->apb);
903	
904	  /* Configure DMA stream */
905	
906	  bytes_queued = esp32s3_dma_setup(outlink, I2S_DMADESC_NUM,
907	                                   bfcontainer->buf,
908	                                   bfcontainer->nbytes, I2S_TX,
909	                                   priv->dma_channel);
910	
911	  if (bytes_queued != bfcontainer->nbytes)
912	    {
913	      i2serr("Failed to enqueue I2S buffer "
914	             "(%" PRIu32 " bytes of %" PRIu32 ")\n",
915	             bytes_queued, bfcontainer->nbytes);
916	      return -bytes_queued;
917	    }
918	
919	  flags = spin_lock_irqsave(&priv->slock);
920	
921	  /* Add the buffer container to the end of the TX pending queue */
922	
923	  sq_addlast((sq_entry_t *)bfcontainer, &priv->tx.pend);
924	
925	  /* Trigger DMA transfer if no transmission is in progress */
926	
927	  ret = i2s_txdma_start(priv);
928	
929	  spin_unlock_irqrestore(&priv->slock, flags);
930	
931	  return ret;
932	}
933	#endif /* I2S_HAVE_TX */
