936	 * Name: i2s_rxdma_setup
937	 *
938	 * Description:
939	 *   Setup the next RX DMA transfer
940	 *
941	 * Input Parameters:
942	 *   priv - Initialized I2S device structure.
943	 *   bfcontainer - The buffer container to be set up
944	 *
945	 * Returned Value:
946	 *   OK on success; a negated errno value on failure
947	 *
948	 * Assumptions:
949	 *   Interrupts are disabled
950	 *
951	 ****************************************************************************/
952	
953	#ifdef I2S_HAVE_RX
954	static int i2s_rxdma_setup(struct esp32s3_i2s_s *priv,
955	                           struct esp32s3_buffer_s *bfcontainer)
956	{
957	  int ret = OK;
958	  struct esp32s3_dmadesc_s *inlink;
959	  uint32_t bytes_queued;
960	  irqstate_t flags;
961	
962	  DEBUGASSERT(bfcontainer && bfcontainer->apb);
963	
964	  inlink = bfcontainer->dma_link;
965	
966	  /* Configure DMA stream */
967	
968	  bytes_queued = esp32s3_dma_setup(inlink, I2S_DMADESC_NUM,
969	                                   bfcontainer->apb->samp,
970	                                   bfcontainer->nbytes, I2S_RX,
971	                                   priv->dma_channel);
972	
973	  if (bytes_queued != bfcontainer->nbytes)
974	    {
975	      i2serr("Failed to enqueue I2S buffer "
976	             "(%" PRIu32 " bytes of %" PRIu32 ")\n",
977	             bytes_queued, bfcontainer->nbytes);
978	      return -bytes_queued;
979	    }
980	
981	  flags = spin_lock_irqsave(&priv->slock);
982	
983	  /* Add the buffer container to the end of the RX pending queue */
984	
985	  sq_addlast((sq_entry_t *)bfcontainer, &priv->rx.pend);
986	
987	  /* Trigger DMA transfer if no transmission is in progress */
988	
989	  ret = i2s_rxdma_start(priv);
990	
991	  spin_unlock_irqrestore(&priv->slock, flags);
992	
993	  return ret;
994	}
