1096	/****************************************************************************
1097	 * Name: i2s_rx_schedule
1098	 *
1099	 * Description:
1100	 *   An RX DMA completion has occurred.  Schedule processing on
1101	 *   the working thread.
1102	 *
1103	 * Input Parameters:
1104	 *   priv - Initialized I2S device structure.
1105	 *   inlink - DMA inlink descriptor that triggered the interrupt.
1106	 *
1107	 * Returned Value:
1108	 *   None
1109	 *
1110	 * Assumptions:
1111	 *   - Interrupts are disabled
1112	 *
1113	 ****************************************************************************/
1114	
1115	#ifdef I2S_HAVE_RX
1116	static void i2s_rx_schedule(struct esp32s3_i2s_s *priv,
1117	                            struct esp32s3_dmadesc_s *inlink)
1118	{
1119	  struct esp32s3_buffer_s *bfcontainer;
1120	  struct esp32s3_dmadesc_s *bfdesc;
1121	  int ret;
1122	
1123	  /* Upon entry, the transfer(s) that just completed are the ones in the
1124	   * priv->rx.act queue.
1125	   */
1126	
1127	  /* Move all entries from the rx.act queue to the rx.done queue */
1128	
1129	  if (!sq_empty(&priv->rx.act))
1130	    {
1131	      /* Remove the next buffer container from the rx.act list */
1132	
1133	      bfcontainer = (struct esp32s3_buffer_s *)sq_peek(&priv->rx.act);
1134	
1135	      /* Find the last descriptor of the current buffer container */
1136	
1137	      bfdesc = bfcontainer->dma_link;
1138	
1139	      while (bfdesc->next != NULL &&
1140	             (bfdesc->next->ctrl & ESP32S3_DMA_CTRL_EOF))
1141	        {
1142	          bfdesc = bfdesc->next;
1143	        }
1144	
1145	      if (bfdesc == inlink)
1146	        {
1147	          sq_remfirst(&priv->rx.act);
1148	
1149	          /* Report the result of the transfer */
1150	
1151	          bfcontainer->result = OK;
1152	
1153	          /* Add the completed buffer container to the tail of the rx.done
1154	           * queue
1155	           */
1156	
1157	          sq_addlast((sq_entry_t *)bfcontainer, &priv->rx.done);
1158	
1159	          /* Check if the DMA is IDLE */
1160	
1161	          if (sq_empty(&priv->rx.act))
1162	            {
1163	              /* Then start the next DMA. */
1164	
1165	              i2s_rxdma_start(priv);
1166	            }
1167	        }
1168	
1169	      /* If the worker has completed running, then reschedule the working
1170	       * thread.
1171	       */
1172	
1173	      if (work_available(&priv->rx.work))
1174	        {
1175	          /* Schedule the RX DMA done processing to occur on the worker
1176	           * thread.
1177	           */
1178	
1179	          ret = work_queue(HPWORK, &priv->rx.work, i2s_rx_worker, priv, 0);
1180	          if (ret != 0)
1181	            {
1182	              i2serr("ERROR: Failed to queue RX work: %d\n", ret);
1183	            }
1184	        }
1185	    }
1186	}
