1205	{
1206	  struct esp32s3_i2s_s *priv = (struct esp32s3_i2s_s *)arg;
1207	  struct esp32s3_buffer_s *bfcontainer;
1208	  irqstate_t flags;
1209	
1210	  DEBUGASSERT(priv);
1211	
1212	  /* When the transfer was started, the active buffer containers were removed
1213	   * from the tx.pend queue and saved in the tx.act queue.  We get here when
1214	   * the DMA is finished.
1215	   *
1216	   * In any case, the buffer containers in tx.act will be moved to the end
1217	   * of the tx.done queue and tx.act will be emptied before this worker is
1218	   * started.
1219	   *
1220	   */
