1238	      /* Perform the TX transfer done callback */
1239	
1240	      DEBUGASSERT(bfcontainer && bfcontainer->callback);
1241	      bfcontainer->callback(&priv->dev, bfcontainer->apb,
1242	                            bfcontainer->arg, bfcontainer->result);
1243	
1244	      /* Release the internal buffer used by the DMA outlink */
1245	
1246	      free(bfcontainer->buf);
1247	
1248	      /* And release the buffer container */
1249	
1250	      i2s_buf_free(priv, bfcontainer);
1251	    }
