1353	            {
1354	              vpd = bfcontainer->dma_link;
1355	              for (i = 0; i < 4 && vpd != NULL; i++)
1356	                {
1357	                  syslog(LOG_ERR,
1358	                         "VP: RXDUMP d[%d] ctrl=%08lx buf=%p next=%p\n",
1359	                         i, (unsigned long)vpd->ctrl, vpd->pbuf, vpd->next);
1360	                  vpd = vpd->next;
1361	                }
1362	            }
1363	        }
1364	    }
1365	#endif /* VELAPAW_I2S_PROBES */
1366	}
