1369	/****************************************************************************
1370	 * Name: i2s_rx_worker
1371	 *
1372	 * Description:
1373	 *   RX transfer done worker
1374	 *
1375	 * Input Parameters:
1376	 *   arg - the I2S device instance cast to void*
1377	 *
1378	 * Returned Value:
1379	 *   None
1380	 *
1381	 ****************************************************************************/
1382	
1383	#ifdef I2S_HAVE_RX
1384	static void i2s_rx_worker(void *arg)
1385	{
1386	  struct esp32s3_i2s_s *priv = (struct esp32s3_i2s_s *)arg;
1387	  struct esp32s3_buffer_s *bfcontainer;
1388	  struct esp32s3_dmadesc_s *dmadesc;
1389	  irqstate_t flags;
1390	
1391	  DEBUGASSERT(priv);
1392	
1393	  /* When the transfer was started, the active buffer containers were removed
1394	   * from the rx.pend queue and saved in the rx.act queue. We get here when
1395	   * the DMA is finished.
1396	   *
1397	   * In any case, the buffer containers in rx.act will be moved to the end
1398	   * of the rx.done queue and rx.act will be emptied before this worker is
1399	   * started.
1400	   *
1401	   */
1402	
1403	
1404	  i2sinfo("rx.act.head=%p rx.done.head=%p\n",
1405	          priv->rx.act.head, priv->rx.done.head);
1406	
1407	  /* Process each buffer in the rx.done queue */
1408	
1409	  while (sq_peek(&priv->rx.done) != NULL)
1410	    {
1411	      /* Remove the buffer container from the rx.done queue.  NOTE that
1412	       * interrupts must be disabled to do this because the rx.done queue is
1413	       * also modified from the interrupt level.
1414	       */
1415	
1416	      flags = spin_lock_irqsave(&priv->slock);
1417	      bfcontainer = (struct esp32s3_buffer_s *)sq_remfirst(&priv->rx.done);
1418	      spin_unlock_irqrestore(&priv->slock, flags);
1419	
1420	      dmadesc = bfcontainer->dma_link;
1421	
1422	      bfcontainer->apb->nbytes = 0;
1423	
1424	      /* VelaPaw patch #10: the loop condition tested EOF on every link,
1425	       * but the hardware sets suc_eof only on the LAST descriptor of a
1426	       * chain.  On any multi-descriptor transfer it therefore exited on
1427	       * d[0] and reported nbytes == 0.  Sum the whole chain, stopping
1428	       * after the descriptor that carries EOF.
1429	       */
1430	
1431	      while (dmadesc != NULL)
1432	        {
1433	          bfcontainer->apb->nbytes +=
1434	              (dmadesc->ctrl >> ESP32S3_DMA_CTRL_DATALEN_S) &
1435	              ESP32S3_DMA_CTRL_DATALEN_V;
1436	
1437	          if (dmadesc->ctrl & ESP32S3_DMA_CTRL_EOF)
1438	            {
1439	              break;
1440	            }
1441	
1442	          dmadesc = dmadesc->next;
1443	        }
1444	
1445	#if VELAPAW_I2S_PROBES
1446	      /* VelaPaw patch #30: count railed samples and report DC offset, to
1447	       * separate genuine clipping (many railed samples) from a structural
1448	       * boundary artifact (a fixed one or two 0x8000 per buffer).
1449	       */
1450	
1451	      {
1452	        static uint32_t vp_seq = 0;
1453	
1454	        if ((vp_seq++ & 7) == 0)
1455	          {
1456	            int16_t *vs = (int16_t *)bfcontainer->apb->samp;
1457	            uint32_t vn = bfcontainer->apb->nbytes / 2;
1458	            uint32_t vi;
1459	            int32_t  vpeak = 0;
1460	            uint32_t vpidx = 0;
1461	            uint32_t vrail = 0;
1462	            uint32_t vm8 = 0;
1463	            int64_t  vdc = 0;
1464	            uint64_t vsum = 0;
1465	
1466	            for (vi = 0; vi < vn; vi++)
1467	              {
1468	                int32_t vv = vs[vi];
1469	
1470	                vdc += vv;
1471	
1472	                if (vv == -32768)
1473	                  {
1474	                    vm8++;
1475	                  }
1476	
1477	                if (vv < 0)
1478	                  {
1479	                    vv = -vv;
1480	                  }
1481	
1482	                if (vv >= 32000)
1483	                  {
1484	                    vrail++;
1485	                  }
1486	
1487	                if (vv > vpeak)
1488	                  {
1489	                    vpeak = vv;
1490	                    vpidx = vi;
1491	                  }
1492	
1493	                vsum += (uint32_t)vv;
1494	              }

1494	              }
1495	
1496	            syslog(LOG_ERR, "VP: mic n=%" PRIu32 " peak=%" PRId32
1497	                            "@%" PRIu32 " mean=%" PRIu32
1498	                            " dc=%" PRId32 " rail=%" PRIu32
1499	                            " m8=%" PRIu32 "\n",
1500	                   vn, vpeak, vpidx,
1501	                   vn ? (uint32_t)(vsum / vn) : 0,
1502	                   vn ? (int32_t)(vdc / (int64_t)vn) : 0, vrail, vm8);
1503	          }
1504	      }
1505	#endif /* VELAPAW_I2S_PROBES */
1506	
1507	      /* Perform the RX transfer done callback */
1508	
1509	      DEBUGASSERT(bfcontainer && bfcontainer->callback);
1510	
1511	      if (priv->streaming == false)
1512	        {
1513	          bfcontainer->apb->flags |= AUDIO_APB_FINAL;
1514	        }
1515	
1516	      bfcontainer->callback(&priv->dev, bfcontainer->apb,
1517	                            bfcontainer->arg, bfcontainer->result);
1518	
1519	      /* Release our reference on the audio buffer. This may very likely
1520	       * cause the audio buffer to be freed.
1521	       */
1522	
1523	      apb_free(bfcontainer->apb);
1524	
1525	      /* And release the buffer container */
1526	
1527	      i2s_buf_free(priv, bfcontainer);
1528	    }
1529	}
1530	#endif /* I2S_HAVE_RX */
