1532	/****************************************************************************
1533	 * Name: i2s_configure
1534	 *
1535	 * Description:
1536	 *   Configure I2S
1537	 *
1538	 * Input Parameters:
1539	 *   priv - Partially initialized I2S device structure.  This function
1540	 *          will complete the I2S specific portions of the initialization
1541	 *
1542	 * Returned Value:
1543	 *   None
1544	 *
1545	 ****************************************************************************/
1546	
1547	static void i2s_configure(struct esp32s3_i2s_s *priv)
1548	{
1549	  uint32_t tx_conf  = 0;
1550	  uint32_t tx_conf1 = 0;
1551	  uint32_t rx_conf  = 0;
1552	  uint32_t rx_conf1 = 0;
1553

3040	 *
3041	 * Returned Value:
3042	 *   OK on success; a negated errno value on failure.
3043	 *
3044	 ****************************************************************************/
3045	
3046	#ifdef I2S_HAVE_TX
3047	static int i2s_send(struct i2s_dev_s *dev, struct ap_buffer_s *apb,
3048	                    i2s_callback_t callback, void *arg, uint32_t timeout)
3049	{
3050	  struct esp32s3_i2s_s *priv = (struct esp32s3_i2s_s *)dev;
3051	
3052	  if (priv->config->tx_en)
3053	    {
3054	      struct esp32s3_buffer_s *bfcontainer;
3055	      int ret = OK;
3056	      uint32_t nbytes;
3057	      uint32_t nsamp;
3058	
3059	      /* Check audio buffer data size from the upper half. If the buffer
3060	       * size is not a multiple of the data width, the remaining bytes
3061	       * must be sent along with the next audio buffer.
3062	       */
3063	
3064	      nbytes = (apb->nbytes - apb->curbyte) + priv->tx.carry.bytes;
3065	
3066	      nbytes -= (nbytes % (priv->data_width / 8));
3067	
3068	      if (nbytes > (ESP32S3_DMA_BUFLEN_MAX * I2S_DMADESC_NUM))
3069	        {
3070	          i2serr("Required buffer size can't fit into DMA outlink "
3071	                 "(exceeds in %" PRIu32 " bytes). Try to increase the "
3072	                 "number of the DMA descriptors (CONFIG_I2S_DMADESC_NUM).",
3073	                 nbytes - (ESP32S3_DMA_BUFLEN_MAX * I2S_DMADESC_NUM));
3074	          return -EFBIG;
3075	        }
3076	
3077	      /* Allocate a buffer container in advance */
3078	
3079	      bfcontainer = i2s_buf_allocate(priv);
3080	      if (bfcontainer == NULL)
3081	        {
3082	          i2serr("Failed to allocate the buffer container");
3083	          return -ENOMEM;
3084	        }
3085	
3086	      /* Get exclusive access to the I2S driver data */
3087	
3088	      ret = nxmutex_lock(&priv->lock);
3089	      if (ret < 0)
3090	        {
3091	          goto errout_with_buf;
3092	        }
3093	
3094	      /* Add a reference to the audio buffer */
3095	
3096	      apb_reference(apb);
3097	
3098	      /* Initialize the buffer container structure */
3099	
3100	      bfcontainer->callback = callback;
3101	      bfcontainer->timeout  = timeout;
3102	      bfcontainer->arg      = arg;
3103	      bfcontainer->apb      = apb;
3104	      bfcontainer->nbytes   = nbytes;
3105	      bfcontainer->result   = -EBUSY;
3106	
3107	      ret = i2s_txdma_setup(priv, bfcontainer);
3108	
3109	      if (ret != OK)
3110	        {
3111	          goto errout_with_buf;
3112	        }
3113	
3114	      i2sinfo("Queued %d bytes into DMA buffers\n", apb->nbytes);
3115	      i2s_dump_buffer("Audio pipeline buffer:", &apb->samp[apb->curbyte],
3116	                      apb->nbytes - apb->curbyte);
3117	
3118	      nxmutex_unlock(&priv->lock);
3119	
3120	      return OK;
3121	
3122	errout_with_buf:
3123	      nxmutex_unlock(&priv->lock);
3124	      i2s_buf_free(priv, bfcontainer);
3125	      return ret;
3126	    }
3127	
3128	  return -ENOTTY;
3129	}

3130	#endif /* I2S_HAVE_TX */
