3132	/****************************************************************************
3133	 * Name: i2s_receive
3134	 *
3135	 * Description:
3136	 *   Receive a block of data on I2S.
3137	 *
3138	 * Input Parameters:
3139	 *   dev      - Device-specific state data
3140	 *   apb      - A pointer to the audio buffer in which to receive data
3141	 *   callback - A user provided callback function that will be called at
3142	 *              the completion of the transfer.
3143	 *   arg      - An opaque argument that will be provided to the callback
3144	 *              when the transfer complete
3145	 *   timeout  - The timeout value to use.  The transfer will be cancelled
3146	 *              and an ETIMEDOUT error will be reported if this timeout
3147	 *              elapsed without completion of the DMA transfer.  Units
3148	 *              are system clock ticks.  Zero means no timeout.
3149	 *
3150	 * Returned Value:
3151	 *   OK on success; a negated errno value on failure.
3152	 *
3153	 ****************************************************************************/
3154	
3155	#ifdef I2S_HAVE_RX
3156	static int i2s_receive(struct i2s_dev_s *dev, struct ap_buffer_s *apb,
3157	                       i2s_callback_t callback, void *arg, uint32_t timeout)
3158	{
3159	  struct esp32s3_i2s_s *priv = (struct esp32s3_i2s_s *)dev;
3160	
3161	
3162	  if (priv->config->rx_en)
3163	    {
3164	      struct esp32s3_buffer_s *bfcontainer;
3165	      int ret = OK;
3166	      uint32_t nbytes;
3167	      uint32_t nsamp;
3168	
3169	      /* Check max audio buffer data size from the upper half and align the
3170	       * receiving buffer according to the data width.
3171	       */
3172	
3173	      nbytes = apb->nmaxbytes;
3174	
3175	      nbytes -= (nbytes % (priv->data_width / 8));
3176	
3177	      nbytes = MIN(nbytes, ESP32S3_DMA_BUFLEN_MAX);
3178	
3179	      /* VelaPaw patch #9: the alignment above happens BEFORE the clamp, so
3180	       * clamping 8192 to ESP32S3_DMA_BUFLEN_MAX yields 4095 -- an odd byte
3181	       * count that lands in I2S_RX_EOF_NUM and can never be reached by
3182	       * whole 16-bit samples.  Re-align after clamping (-> 4092).
3183	       */
3184	
3185	      nbytes &= ~UINT32_C(3);
3186	
3187	      /* Allocate a buffer container in advance */
3188	
3189	      bfcontainer = i2s_buf_allocate(priv);
3190	      if (bfcontainer == NULL)
3191	        {
3192	          i2serr("Failed to allocate the buffer container");
3193	          return -ENOMEM;
3194	        }
3195	
3196	      /* Get exclusive access to the I2S driver data */
3197	
3198	      ret = nxmutex_lock(&priv->lock);
3199	      if (ret < 0)
3200	        {
3201	          goto errout_with_buf;
3202	        }
3203	
3204	      /* Add a reference to the audio buffer */
3205	
3206	      apb_reference(apb);
3207	
3208	      /* Initialize the buffer container structure */
3209	
3210	      bfcontainer->callback = callback;
3211	      bfcontainer->timeout  = timeout;
3212	      bfcontainer->arg      = arg;
3213	      bfcontainer->apb      = apb;
3214	      bfcontainer->nbytes   = nbytes;
3215	      bfcontainer->result   = -EBUSY;
3216	
3217	      /* VelaPaw patch #11: es8311.c contains no I2S_IOCTL call at all, so
3218	       * AUDIOIOC_START never reaches this lower half and priv->streaming
3219	       * stays false -- which makes i2s_rx_worker stamp every buffer
3220	       * AUDIO_APB_FINAL and kill the capture after one block.
3221	       */
3222	
3223	      priv->streaming = true;
3224	
3225	      ret = i2s_rxdma_setup(priv, bfcontainer);
3226	
3227	      if (ret != OK)
3228	        {
3229	          goto errout_with_buf;
3230	        }
3231	
3232	      i2sinfo("Prepared %d bytes to receive DMA buffers\n", apb->nmaxbytes);
3233	      i2s_dump_buffer("Audio pipeline buffer:", &apb->samp[apb->curbyte],
3234	                      apb->nbytes - apb->curbyte);
3235	
3236	      nxmutex_unlock(&priv->lock);
3237	
3238	      return OK;
3239	
3240	errout_with_buf:
3241	      nxmutex_unlock(&priv->lock);
3242	      i2s_buf_free(priv, bfcontainer);
3243	      return ret;
3244	    }
3245	
3246	  return -ENOTTY;
3247	}
3248	#endif /* I2S_HAVE_RX */
