63	 * Public Functions
64	 ****************************************************************************/
65	
66	/****************************************************************************
67	 * Name: esp32s3_dma_request
68	 *
69	 * Description:
70	 *   Request DMA channel and config it with given parameters.
71	 *
72	 * Input Parameters:
73	 *   periph   - Peripheral for which the DMA channel request was made
74	 *   tx_prio  - Interrupt priority
75	 *   rx_prio  - Interrupt flags
76	 *   burst_en - Enable burst transmission
77	 *
78	 * Returned Value:
79	 *   DMA channel number (>=0) if success or -1 if fail.
80	 *
81	 ****************************************************************************/
82	
83	int32_t esp32s3_dma_request(enum esp32s3_dma_periph_e periph,
84	                            uint32_t tx_prio,
85	                            uint32_t rx_prio,
86	                            bool burst_en)
87	{
88	  int chan;
89	
90	  DEBUGASSERT(periph  < ESP32S3_DMA_PERIPH_NUM);
91	
92	  DEBUGASSERT(tx_prio <= ESP32S3_DMA_TX_PRIO_MAX);
93	  DEBUGASSERT(rx_prio <= ESP32S3_DMA_RX_PRIO_MAX);
94	
95	  dmainfo("periph=%" PRIu32 " tx_prio=%" PRIu32 " rx_prio=%" PRIu32 "\n",
96	          (uint32_t)periph, tx_prio, rx_prio);
97	
98	  nxmutex_lock(&g_dma_lock);
99	
100	  for (chan = 0; chan < ESP32S3_DMA_CHAN_MAX; chan++)
101	    {
102	      if (!g_dma_chan_used[chan])
103	        {
104	          g_dma_chan_used[chan] = true;
105	          break;
106	        }
107	    }
108	
109	  if (chan == ESP32S3_DMA_CHAN_MAX)
110	    {
111	      dmaerr("No available GDMA channel for allocation\n");
112	
113	      nxmutex_unlock(&g_dma_lock);
114	      return ERROR;
115	    }
116	
117	  dmainfo("Allocated channel=%d\n", chan);
118	
119	  if (periph == ESP32S3_DMA_PERIPH_MEM)
120	    {
121	      /* Enable DMA channel M2M mode */
122	
123	      SET_GDMA_CH_BITS(DMA_IN_CONF0_CH0_REG, chan, DMA_MEM_TRANS_EN_CH0_M);
124	
125	      /* Just setting a valid value to the register */
126	
127	      SET_GDMA_CH_REG(DMA_OUT_PERI_SEL_CH0_REG, chan, 0);
128	      SET_GDMA_CH_REG(DMA_IN_PERI_SEL_CH0_REG, chan, 0);
129	    }
130	  else
131	    {
132	      /* Disable DMA channel M2M mode */
133	
134	      CLR_GDMA_CH_BITS(DMA_IN_CONF0_CH0_REG, chan, DMA_MEM_TRANS_EN_CH0_M);
135	
136	      /* Connect DMA TX/RX channels to a given peripheral */
137	
138	      SET_GDMA_CH_REG(DMA_OUT_PERI_SEL_CH0_REG, chan, periph);
139	      SET_GDMA_CH_REG(DMA_IN_PERI_SEL_CH0_REG, chan, periph);
140	    }
141	
142	  if (burst_en)
143	    {
144	      /* Enable DMA TX/RX channels burst sending data */
145	
146	      SET_GDMA_CH_BITS(DMA_OUT_CONF0_CH0_REG, chan,
147	                       DMA_OUT_DATA_BURST_EN_CH0_M);
148	      SET_GDMA_CH_BITS(DMA_IN_CONF0_CH0_REG, chan,
149	                       DMA_IN_DATA_BURST_EN_CH0_M);
150	
151	      /* Enable DMA TX/RX channels burst reading descriptor link */
152	
153	      SET_GDMA_CH_BITS(DMA_OUT_CONF0_CH0_REG, chan,
154	                       DMA_OUTDSCR_BURST_EN_CH0_M);
155	      SET_GDMA_CH_BITS(DMA_IN_CONF0_CH0_REG, chan,
156	                       DMA_INDSCR_BURST_EN_CH0_M);
157	    }
158	
159	  /* Set priority for DMA TX/RX channels */
160	
161	  SET_GDMA_CH_REG(DMA_OUT_PRI_CH0_REG, chan, tx_prio);
162	  SET_GDMA_CH_REG(DMA_IN_PRI_CH0_REG, chan, rx_prio);
163	
164	  nxmutex_unlock(&g_dma_lock);
165	  return chan;
166	}
