168	/****************************************************************************
169	 * Name: esp32s3_dma_release
170	 *
171	 * Description:
172	 *   Release DMA channel from peripheral.
173	 *
174	 * Input Parameters:
175	 *   chan - Peripheral for which the DMA channel request was made
176	 *
177	 * Returned Value:
178	 *   None.
179	 *
180	 ****************************************************************************/
181	
182	void esp32s3_dma_release(int chan)
183	{
184	  DEBUGASSERT(chan  < ESP32S3_DMA_CHAN_MAX);
185	
186	  nxmutex_lock(&g_dma_lock);
187	
188	  /* Disconnect DMA TX channel from peripheral */
189	
190	  SET_GDMA_CH_REG(DMA_OUT_PERI_SEL_CH0_REG, chan, DMA_INVALID_PERIPH_ID);
191	
192	  /* Disconnect DMA RX channel from peripheral */
193	
194	  SET_GDMA_CH_REG(DMA_IN_PERI_SEL_CH0_REG, chan, DMA_INVALID_PERIPH_ID);
195	  CLR_GDMA_CH_BITS(DMA_IN_CONF0_CH0_REG, chan, DMA_MEM_TRANS_EN_CH0_M);
196	
197	  /* Disable DMA TX/RX channels burst sending data */
198	
199	  CLR_GDMA_CH_BITS(DMA_OUT_CONF0_CH0_REG, chan, DMA_OUT_DATA_BURST_EN_CH0_M);
200	  CLR_GDMA_CH_BITS(DMA_IN_CONF0_CH0_REG, chan, DMA_IN_DATA_BURST_EN_CH0_M);
201	
202	  /* Disable DMA TX/RX channels burst reading descriptor link */
203	
204	  CLR_GDMA_CH_BITS(DMA_OUT_CONF0_CH0_REG, chan, DMA_OUTDSCR_BURST_EN_CH0_M);
205	  CLR_GDMA_CH_BITS(DMA_IN_CONF0_CH0_REG, chan, DMA_INDSCR_BURST_EN_CH0_M);
