217	/****************************************************************************
218	 * Name: esp32s3_dma_setup
219	 *
220	 * Description:
221	 *   Initialize the DMA inlink/outlink (linked list) and bind the target
222	 *   buffer to its DMA descriptors.
223	 *
224	 * Input Parameters:
225	 *   dmadesc - Pointer to the DMA descriptors
226	 *   num     - Number of DMA descriptors
227	 *   pbuf    - RX/TX buffer pointer
228	 *   len     - RX/TX buffer length
229	 *   tx      - true: TX mode (transmitter); false: RX mode (receiver)
230	 *   chan    - DMA channel of the receiver/transmitter
231	 *
232	 * Returned Value:
233	 *   Bound pbuf data bytes
234	 *
235	 ****************************************************************************/
236	
237	uint32_t esp32s3_dma_setup(struct esp32s3_dmadesc_s *dmadesc, uint32_t num,
238	                           uint8_t *pbuf, uint32_t len, bool tx, int chan)
239	{
240	  int i;
241	  uint32_t regval;
242	  uint32_t bytes = len;
243	  uint8_t *pdata = pbuf;
244	  uint32_t data_len;
245	  uint32_t buf_len;
246	  int alignment = 4;
247	  int dma_size = ESP32S3_DMA_BUFFER_MAX_SIZE;
248	  bool buffer_in_psram = esp32s3_ptr_extram(pdata);
249	  int block_size_index = 0;
250	  uint32_t addr = GDMA_CH_REG_ADDR(DMA_IN_CONF0_CH0_REG, chan);
251	  bool burst_en = REG_GET_FIELD(addr, DMA_IN_DATA_BURST_EN_CH0);
252	
253	  DEBUGASSERT(dmadesc != NULL);
254	  DEBUGASSERT(num > 0);
255	  DEBUGASSERT(pbuf != NULL);
256	  DEBUGASSERT(len > 0);
257	  DEBUGASSERT(chan >= 0 && chan  < ESP32S3_DMA_CHAN_MAX);
258	
259	  if (!tx && buffer_in_psram)
260	    {
261	      addr = GDMA_CH_REG_ADDR(DMA_IN_CONF1_CH0_REG, chan);
262	      block_size_index = REG_GET_FIELD(addr, DMA_IN_EXT_MEM_BK_SIZE_CH0);
263	      switch (block_size_index)
264	        {
265	          case ESP32S3_DMA_EXT_MEMBLK_64B:
266	            alignment = 64;
267	            break;
268	
269	          case ESP32S3_DMA_EXT_MEMBLK_32B:
270	            alignment = 32;
271	            break;
272	
273	          case ESP32S3_DMA_EXT_MEMBLK_16B:
274	          default:
275	            alignment = 16;
276	            break;
277	        }
278	
279	      dma_size = 0x1000 - alignment;
280	    }
281	  else if(!tx && burst_en)
282	    {
283	      dma_size = ESP32S3_DMA_BUFLEN_MAX_4B_ALIGNED;
284	    }
285	
286	  for (i = 0; i < num; i++)
287	    {
288	      data_len = MIN(bytes, dma_size);
289	      if (!tx && (burst_en || buffer_in_psram))
290	        {
291	          /* Buffer length must be rounded to next alignment boundary. */
292	
293	          buf_len = ALIGN_UP(data_len, alignment);
294	        }
295	      else
296	        {
297	          buf_len = data_len;
298	        }
299	
300	      dmadesc[i].ctrl = ESP32S3_DMA_CTRL_OWN;
301	
302	      /* Only set Data Length if it's a TX buffer. Otherwise, it will be
303	       * written automatically by hardware.
304	       */
305	
306	      if (tx)
307	        {
308	          dmadesc[i].ctrl |= (data_len << ESP32S3_DMA_CTRL_DATALEN_S);
309	        }
310	
311	      dmadesc[i].ctrl |= (buf_len << ESP32S3_DMA_CTRL_BUFLEN_S);
312	      dmadesc[i].pbuf = pdata;
313	      dmadesc[i].next = &dmadesc[i + 1];
314	
315	      bytes -= data_len;
316	      if (bytes == 0)
317	        {
318	          break;
319	        }
320	
321	      pdata += data_len;
322	    }
323	
324	  /* suc_eof (defined by ESP32S3_DMA_CTRL_EOF) is set by software
325	   * only in transmit descriptor.
326	   */
327	
328	  if (tx)
329	    {
330	      dmadesc[i].ctrl |= ESP32S3_DMA_CTRL_EOF;
331	    }
332	
333	  dmadesc[i].next  = NULL;
334	
335	  return len - bytes;
336	}
