338	/****************************************************************************
339	 * Name: esp32s3_dma_load
340	 *
341	 * Description:
342	 *   Load the address of the first DMA descriptor of an already bound
343	 *   inlink/outlink to the corresponding GDMA_<IN/OUT>LINK_ADDR_CHn register
344	 *
345	 * Input Parameters:
346	 *   dmadesc - Pointer of the previously bound inlink/outlink
347	 *   chan    - DMA channel of the receiver/transmitter
348	 *   tx      - true: TX mode (transmitter); false: RX mode (receiver)
349	 *
350	 * Returned Value:
351	 *   None
352	 *
353	 ****************************************************************************/
354	
355	void esp32s3_dma_load(struct esp32s3_dmadesc_s *dmadesc, int chan, bool tx)
356	{
357	  uint32_t regval;
358	
359	  DEBUGASSERT(chan >= 0);
360	  DEBUGASSERT(dmadesc != NULL);
361	
362	  if (tx)
363	    {
364	      /* Reset DMA TX channel FSM and FIFO pointer */
365	
366	      SET_GDMA_CH_BITS(DMA_OUT_CONF0_CH0_REG, chan, DMA_OUT_RST_CH0_M);
367	      CLR_GDMA_CH_BITS(DMA_OUT_CONF0_CH0_REG, chan, DMA_OUT_RST_CH0_M);
368	
369	      /* Set the descriptor link base address for TX channel */
370	
371	      regval = (uint32_t)dmadesc & DMA_OUTLINK_ADDR_CH0;
372	      CLR_GDMA_CH_BITS(DMA_OUT_LINK_CH0_REG, chan, DMA_OUTLINK_ADDR_CH0);
373	      SET_GDMA_CH_BITS(DMA_OUT_LINK_CH0_REG, chan, regval);
374	    }
375	  else
376	    {
377	      /* Reset DMA RX channel FSM and FIFO pointer */
378	
379	      SET_GDMA_CH_BITS(DMA_IN_CONF0_CH0_REG, chan, DMA_IN_RST_CH0_M);
380	      CLR_GDMA_CH_BITS(DMA_IN_CONF0_CH0_REG, chan, DMA_IN_RST_CH0_M);
381	
382	      /* Set the descriptor link base address for RX channel */
383	
384	      regval = (uint32_t)dmadesc & DMA_INLINK_ADDR_CH0;
385	      CLR_GDMA_CH_BITS(DMA_IN_LINK_CH0_REG, chan, DMA_INLINK_ADDR_CH0);
386	      SET_GDMA_CH_BITS(DMA_IN_LINK_CH0_REG, chan, regval);
387	    }
388	}
