476	 * Description:
477	 *   Wait until transmission ends.
478	 *
479	 * Input Parameters:
480	 *   chan - DMA channel
481	 *   tx   - true: TX mode; false: RX mode
482	 *
483	 * Returned Value:
484	 *   None.
485	 *
486	 ****************************************************************************/
487	
488	void esp32s3_dma_wait_idle(int chan, bool tx)
489	{
490	  uint32_t regval;
491	  uint32_t regaddr;
492	  uint32_t waitbits;
493	
494	  if (tx)
495	    {
496	      regaddr  = DMA_OUT_LINK_CH0_REG + chan * GDMA_REG_OFFSET;
497	      waitbits = DMA_OUTLINK_PARK_CH0;
498	    }
499	  else
500	    {
501	      regaddr  = DMA_IN_LINK_CH0_REG + chan * GDMA_REG_OFFSET;
502	      waitbits = DMA_INLINK_PARK_CH0;
503	    }
504	
505	  do
506	    {
507	      regval = getreg32(regaddr);
508	    }
509	  while ((waitbits & regval) == 0);
510	}
