35	static const char *TAG = "heartbeat";
36	
37	#define HEARTBEAT_PROMPT \
38	    "Read " AGENT_HEARTBEAT_FILE " and follow any instructions or tasks listed there. " \
39	    "If nothing needs attention, reply with just: HEARTBEAT_OK"
40	
41	static volatile bool s_heartbeat_running = false;
42	
43	/* ── Content check ────────────────────────────────────────────── */
44	
45	/**
46	 * Check if HEARTBEAT.md has actionable content.
47	 * Returns true if any line is NOT:
48	 *   - empty / whitespace-only
49	 *   - a markdown header (starts with #)
50	 *   - a completed checkbox (- [x] or * [x])
51	 */
52	static bool heartbeat_has_tasks(void)
53	{
54	    FILE *f = fopen(AGENT_HEARTBEAT_FILE, "r");
55	    if (!f) {
56	        return false;
57	    }
58	
59	    char line[256];
60	    bool found_task = false;
61	
62	    while (fgets(line, sizeof(line), f)) {
63	        /* Skip leading whitespace */
64	        const char *p = line;
65	        while (*p && isspace((unsigned char)*p)) {
66	            p++;
67	        }
68	
69	        /* Skip empty lines */
70	        if (*p == '\0') {
71	            continue;
72	        }
73	
74	        /* Skip markdown headers */
75	        if (*p == '#') {
76	            continue;
77	        }
78	
79	        /* Skip completed checkboxes: "- [x]" or "* [x]" */
80	        if ((*p == '-' || *p == '*') && *(p + 1) == ' ' && *(p + 2) == '[') {
81	            char mark = *(p + 3);
82	            if ((mark == 'x' || mark == 'X') && *(p + 4) == ']') {
83	                continue;
84	            }
85	        }
86	
87	        /* Found an actionable line */
88	        found_task = true;
89	        break;
90	    }
91	
92	    fclose(f);
93	    return found_task;
94	}
95	
96	/* ── Send heartbeat to agent ──────────────────────────────────── */
97	
98	static bool heartbeat_send(void)
99	{
100	    if (!heartbeat_has_tasks()) {
101	        return false;
102	    }
103	
104	    agent_msg_t msg;
105	    memset(&msg, 0, sizeof(msg));
106	    strncpy(msg.channel, AGENT_CHAN_SYSTEM, sizeof(msg.channel) - 1);
107	    strncpy(msg.chat_id, AGENT_HEARTBEAT_CHAT_ID, sizeof(msg.chat_id) - 1);
108	    msg.content = strdup(HEARTBEAT_PROMPT);
109	
110	    if (!msg.content) {
111	        syslog(LOG_ERR, "[%s] Failed to allocate heartbeat prompt\n", TAG);
112	        return false;
113	    }
114	
115	    int err = message_bus_push_inbound(&msg);
116	    if (err != OK) {
117	        syslog(LOG_WARNING, "[%s] Failed to push heartbeat message: %s\n", TAG, strerror(errno));
118	        free(msg.content);
119	        return false;
120	    }
121	
122	    syslog(LOG_INFO, "[%s] Triggered agent check\n", TAG);
123	    return true;
124	}
