127	static void *heartbeat_thread(void *arg)
128	{
129	    (void)arg;
130	
131	    /* llmdbg-hb round 7: one-shot opendir() control test from a pthread
132	     * that is NOT agent_loop, to isolate whether the opendir() hang is
133	     * specific to agent_loop's call context or affects any
134	     * agent_task_create()-spawned pthread calling opendir(). */
135	    (void)0;  // DBGOFF: syslog(LOG_INFO, "[llmdbg-hb] tid=%p: before opendir(%s)\n", (void*)pthread_self(), AGENT_SKILLS_DIR);
136	    DIR *__hbdir = opendir(AGENT_SKILLS_DIR);
137	    (void)0;  // DBGOFF: syslog(LOG_INFO, "[llmdbg-hb] tid=%p: after opendir dir=%p\n", (void*)pthread_self(), (void*)__hbdir);
138	    if (__hbdir) {
139	        closedir(__hbdir);
140	        (void)0;  // DBGOFF: syslog(LOG_INFO, "[llmdbg-hb] tid=%p: after closedir\n", (void*)pthread_self());
141	    }
142	
143	    while (s_heartbeat_running) {
144	        /* Sleep for the heartbeat interval (use sleep() to avoid usleep overflow) */
145	        sleep(AGENT_HEARTBEAT_INTERVAL_MS / 1000);
146	        heartbeat_send();
147	    }
148	
149	    return NULL;
150	}
