154	int heartbeat_init(void)
155	{
156	    syslog(LOG_INFO, "[%s] Heartbeat service initialized (file: %s, interval: %ds)\n", TAG, AGENT_HEARTBEAT_FILE, AGENT_HEARTBEAT_INTERVAL_MS / 1000);
157	    return OK;
158	}
