160	int heartbeat_start(void)
161	{
162	    if (s_heartbeat_running) {
163	        syslog(LOG_WARNING, "[%s] Heartbeat timer already running\n", TAG);
164	        return OK;
165	    }
166	
167	    s_heartbeat_running = true;
168	
169	    int err = agent_task_create(
170	        heartbeat_thread,
171	        "heartbeat",
172	        4096,
173	        NULL,
174	        3
175	    );
176	
177	    if (err != OK) {
178	        s_heartbeat_running = false;
179	        syslog(LOG_ERR, "[%s] Failed to create heartbeat thread\n", TAG);
180	        return ERROR;
181	    }
182	
183	    syslog(LOG_INFO, "[%s] Heartbeat started (every %d min)\n", TAG, AGENT_HEARTBEAT_INTERVAL_MS / 60000);
184	    return OK;
185	}
186	
187	void heartbeat_stop(void)
188	{
189	    if (s_heartbeat_running) {
190	        s_heartbeat_running = false;
191	        /* Thread will exit on next iteration */
192	        syslog(LOG_INFO, "[%s] Heartbeat stopped\n", TAG);
193	    }
194	}
195	
196	bool heartbeat_trigger(void)
197	{
198	    return heartbeat_send();
199	}
