1469	/* ── Build messages array from session history + current msg ─ */
1470	
1471	static cJSON* build_messages(const char* chat_id, const char* content,
1472	    char* history_json, size_t hist_size)
1473	{
1474	    /* velapaw: heartbeat is stateless by design.  Replaying the
1475	     * previous firing's history made the digest answer from stale
1476	     * device state -- a pet fed at 14:00 was still "unfed" to the
1477	     * 14:30 firing -- and grew the request from ~9 KB to ~14 KB.
1478	     * Every firing must go back and read the real files.
1479	     * history_json is allocated once outside the message loop, so
1480	     * clear it explicitly; calloc only zeroes it for the first msg.
1481	     */
1482	    if (strcmp(chat_id, AGENT_HEARTBEAT_CHAT_ID) == 0) {
1483	        history_json[0] = '\0';
1484	    } else {
1485	        session_get_history_json(chat_id, history_json, hist_size,
1486	            AGENT_AI_AGENT_MAX_HISTORY);
1487	    }
1488	
1489	    cJSON* messages = cJSON_Parse(history_json);
1490	
1491	    if (!messages) {
1492	        messages = cJSON_CreateArray();
1493	    }
1494	
1495	    /* velapaw: the console chat legitimately wants its history, but the
1496	     * model was treating its own earlier answer as current fact --
1497	     * "today's Jay digest I gave you earlier" -- and replied without
1498	     * opening a single file (iters=1 tools=0), missing a pet whose
1499	     * intake had since fallen below the concern threshold.  Device state
1500	     * changes between turns; replayed text does not.  Put the reminder
1501	     * AFTER the history and immediately BEFORE the new user message so
1502	     * recency works for us instead of against us.  Guarded on a
1503	     * non-empty array: a first turn pays nothing, and the heartbeat --
1504	     * whose history_json is cleared above -- never sees it.
1505	     */
1506	    if (cJSON_GetArraySize(messages) > 0) {
1507	        cJSON* fresh_hint = cJSON_CreateObject();
1508	
1509	        cJSON_AddStringToObject(fresh_hint, "role", "system");
1510	        cJSON_AddStringToObject(fresh_hint, "content",
1511	            "Device state may have changed since the earlier messages in "
1512	            "this conversation. Any figure quoted earlier is stale and must "
1513	            "not be reused as if it were current. Before answering anything "
1514	            "about the present state of the device, its pets, or today's "
1515	            "activity, re-read the relevant files with read_file.");
1516	        cJSON_AddItemToArray(messages, fresh_hint);
1517	    }
1518	
1519	    cJSON* user_msg = cJSON_CreateObject();
1520	
1521	    cJSON_AddStringToObject(user_msg, "role", "user");
1522	    cJSON_AddStringToObject(user_msg, "content", content);
1523	    cJSON_AddItemToArray(messages, user_msg);
1524	    return messages;
1525	}
