1	/****************************************************************************
2	 * VelaPaw - enrollment store + cosine matcher (in-memory)
3	 *
4	 * Persistence is delegated to store/ (stub for now). Embeddings are assumed
5	 * L2-normalized, so cosine similarity == dot product.
6	 ****************************************************************************/
7	
8	#include <string.h>
9	#include <math.h>
10	#include <stdio.h>
11	#include <stdint.h>
12	#include <pthread.h>
13	#include "identity/identity.h"
14	
15	static struct velapaw_pet g_pets[VELAPAW_MAX_PETS];
16	static int                g_npets;
17	
18	/****************************************************************************
19	 * Flash persistence: enrolled pets survive a reset / power-off.
20	 *
21	 * Layout at VELAPAW_PET_FLASH_OFF (well past the models @0x600000 / @0x760000):
22	 *   magic "VPAW" | version | npets | g_pets[npets]      (raw POD copy)
23	 * A blank or garbage sector fails the magic check and reads as "no pets",
24	 * so we never restore nonsense.
25	 *
26	 * IMPORTANT: erase/write SUSPEND THE FLASH CACHE, so they must not run on a
27	 * PSRAM stack (the velapaw task's stack is PSRAM). Same trap the model loader
28	 * hit -- so, like backend_tflm.cc, we run them on a pthread whose stack is an
29	 * internal-RAM .bss buffer.
30	 ****************************************************************************/
31	
32	extern int spi_flash_read(uint32_t src, void *dst, uint32_t size);
33	extern int spi_flash_write(uint32_t dst, const void *src, uint32_t size);
34	extern int spi_flash_erase_range(uint32_t start, uint32_t size);
35	
36	#define VELAPAW_PET_FLASH_OFF  0x800000u          /* 8MB mark, past the models */
37	#define VELAPAW_PET_MAGIC      0x57415056u        /* "VPAW" */
38	#define VELAPAW_PET_VERSION    1u
39	
40	/* Header only (12 B). We deliberately do NOT keep a serialization copy of the
41	 * pets -- we write/read g_pets[] in place, so the RAM cost here is just the
42	 * header + the flash thread stack (~4 KB), not another 4.5 KB of pets. */
43	struct pet_hdr { uint32_t magic; uint32_t version; uint32_t npets; };
44	
45	#define PET_HDR_RESERVED  16u                     /* keeps pets 16-B aligned */
46	#define PET_AREA_BYTES    8192u                   /* 2 x 4 KB flash sectors  */
47	
48	static struct pet_hdr g_hdr;                      /* 12 bytes, .bss          */
49	static uint8_t g_pet_flash_stack[4096];           /* internal-RAM stack      */
50	
51	/* --- per-pet card icons ---------------------------------------------------
52	 * Kept in a SEPARATE flash region from the pet record so old pets still load,
53	 * and written only at enroll/delete (not on every schedule edit). The icon
54	 * buffers live in .bss (internal SRAM), so the flash write reads them
55	 * coherently while the cache is suspended -- no PSRAM bounce needed. */
56	#define VELAPAW_ICON_PX        (VELAPAW_ICON_W * VELAPAW_ICON_H)
57	#define VELAPAW_ICON_FLASH_OFF 0x810000u          /* past the pet record       */
58	#define VELAPAW_ICON_MAGIC     0x4E434956u        /* "VICN"                    */
59	#define VELAPAW_ICON_AREA_BYTES 32768u            /* 8 x 4 KB sectors          */
60	
61	static uint16_t g_icon[VELAPAW_MAX_PETS][VELAPAW_ICON_PX];  /* ~25 KB .bss     */
62	static uint8_t  g_icon_valid[VELAPAW_MAX_PETS];             /* has an icon?    */
63	struct icon_hdr { uint32_t magic; uint32_t version; };
64	static struct icon_hdr g_ihdr;
65	
66	struct pet_io { int write; int rc; };
67	
68	/* Runs on the internal-RAM-stack thread: flash erase/write suspend the cache,
69	 * so none of this may execute on the velapaw task's PSRAM stack. */
70	static void *pet_flash_thread(void *arg)
71	{
72	  struct pet_io *io = (struct pet_io *)arg;
73	
74	  if (io->write)
75	    {
76	      io->rc = spi_flash_erase_range(VELAPAW_PET_FLASH_OFF, PET_AREA_BYTES);
77	      if (io->rc >= 0)
78	        {
79	          io->rc = spi_flash_write(VELAPAW_PET_FLASH_OFF, &g_hdr, sizeof(g_hdr));
80	        }
81	      if (io->rc >= 0)
82	        {
83	          io->rc = spi_flash_write(VELAPAW_PET_FLASH_OFF + PET_HDR_RESERVED,
84	                                   g_pets, sizeof(g_pets));
85	        }
86	    }
87	  else
88	    {
89	      io->rc = spi_flash_read(VELAPAW_PET_FLASH_OFF, &g_hdr, sizeof(g_hdr));
90	      if (io->rc >= 0 &&
91	          g_hdr.magic   == VELAPAW_PET_MAGIC &&
92	          g_hdr.version == VELAPAW_PET_VERSION &&
93	          g_hdr.npets   <= VELAPAW_MAX_PETS)
94	        {
95	          /* header is good -> only now do we overwrite g_pets */
96	          io->rc = spi_flash_read(VELAPAW_PET_FLASH_OFF + PET_HDR_RESERVED,
97	                                  g_pets, sizeof(g_pets));
98	        }
99	      else
100	        {
101	          io->rc = -1;                            /* blank/garbage -> no pets */
102	        }
103	    }
104	  return NULL;
105	}
106	
107	static int pet_flash_run(int write)
108	{
109	  struct pet_io io = { write, -1 };
110	  pthread_attr_t attr;
111	  pthread_t th;
112	  pthread_attr_init(&attr);
113	  pthread_attr_setstack(&attr, g_pet_flash_stack, sizeof(g_pet_flash_stack));
114	  if (pthread_create(&th, &attr, pet_flash_thread, &io) != 0)
115	    {
116	      pthread_attr_destroy(&attr);
117	      return -1;
118	    }
119	  pthread_join(th, NULL);
120	  pthread_attr_destroy(&attr);
121	  return io.rc;
122	}
123	
124	int velapaw_identity_save(void)
125	{
126	  g_hdr.magic   = VELAPAW_PET_MAGIC;
127	  g_hdr.version = VELAPAW_PET_VERSION;
128	  g_hdr.npets   = (uint32_t)g_npets;
129	  int rc = pet_flash_run(1);
130	  printf("velapaw/identity: saved %d pet(s) to flash rc=%d\n", g_npets, rc);
131	  return rc;
132	}
133	
134	/* Icon flash I/O, same internal-RAM-stack pattern as the pets. Reuses the pet
135	 * flash stack (they never run at the same time). */
136	static void *icon_flash_thread(void *arg)
137	{
138	  struct pet_io *io = (struct pet_io *)arg;
139	
140	  if (io->write)
141	    {
142	      g_ihdr.magic = VELAPAW_ICON_MAGIC; g_ihdr.version = 1;
143	      io->rc = spi_flash_erase_range(VELAPAW_ICON_FLASH_OFF,
144	                                     VELAPAW_ICON_AREA_BYTES);
145	      if (io->rc >= 0)
146	        io->rc = spi_flash_write(VELAPAW_ICON_FLASH_OFF, &g_ihdr, sizeof(g_ihdr));
147	      if (io->rc >= 0)
148	        io->rc = spi_flash_write(VELAPAW_ICON_FLASH_OFF + 16,
149	                                 g_icon_valid, sizeof(g_icon_valid));
150	      if (io->rc >= 0)
151	        io->rc = spi_flash_write(VELAPAW_ICON_FLASH_OFF + 32,
152	                                 g_icon, sizeof(g_icon));
153	    }
154	  else
155	    {
156	      io->rc = spi_flash_read(VELAPAW_ICON_FLASH_OFF, &g_ihdr, sizeof(g_ihdr));
157	      if (io->rc >= 0 && g_ihdr.magic == VELAPAW_ICON_MAGIC)
158	        {
159	          spi_flash_read(VELAPAW_ICON_FLASH_OFF + 16,
160	                         g_icon_valid, sizeof(g_icon_valid));
161	          spi_flash_read(VELAPAW_ICON_FLASH_OFF + 32, g_icon, sizeof(g_icon));
162	        }
163	      else
164	        {
165	          io->rc = -1;                         /* blank/old flash -> no icons */
166	        }
167	    }
168	  return NULL;
169	}
170	
171	static int icon_flash_run(int write)
172	{
173	  struct pet_io io = { write, -1 };
174	  pthread_attr_t attr; pthread_t th;
175	  pthread_attr_init(&attr);
176	  pthread_attr_setstack(&attr, g_pet_flash_stack, sizeof(g_pet_flash_stack));
177	  if (pthread_create(&th, &attr, icon_flash_thread, &io) != 0)
178	    {
179	      pthread_attr_destroy(&attr);
180	      return -1;
181	    }
182	  pthread_join(th, NULL);
183	  pthread_attr_destroy(&attr);
184	  return io.rc;
185	}
