213	int velapaw_identity_load(void)
214	{
215	  /* icons load independently -- old pets have none */
216	  if (icon_flash_run(0) < 0)
217	    {
218	      memset(g_icon_valid, 0, sizeof(g_icon_valid));
219	    }
220	
221	  if (pet_flash_run(0) < 0)
222	    {
223	      printf("velapaw/identity: no saved pets (blank/invalid flash)\n");
224	      g_npets = 0;
225	      return -1;
226	    }
227	  g_npets = (int)g_hdr.npets;
228	  printf("velapaw/identity: restored %d pet(s) from flash\n", g_npets);
229	  return g_npets;
230	}
