240	/* The on-screen enroll keyboard admits a stray comma or a double space, and
241	 * this is the only place a name becomes persistent, so trimming here covers
242	 * the dialog, the CLI and any future agent tool at once.  Junk in a name
243	 * lands in status.md as a broken markdown heading and makes one animal look
244	 * like two distinct keys.
245	 */
246	static void vp_copy_name(char *dst, size_t cap, const char *src)
247	{
248	  size_t n;
249	
250	  if (src == NULL)
251	    {
252	      src = "pet";
253	    }
254	
255	  while (*src == ' ' || *src == '\t')
256	    {
257	      src++;
258	    }
259	
260	  n = strnlen(src, cap - 1);
261	  while (n > 0 && strchr(" \t,;.", src[n - 1]) != NULL)
262	    {
263	      n--;
264	    }
265	
266	  if (n == 0)
267	    {
268	      src = "pet";
269	      n   = 3;
270	    }
271	
272	  memcpy(dst, src, n);
273	  dst[n] = '\0';
274	}
