291	velapaw_pet_id_t velapaw_identity_enroll(
292	    const char *name, int portion_g, int cooldown_s, int daily_limit_g,
293	    const int *meal_min,
294	    const float (*samples)[VELAPAW_EMBED_DIM], int n_samples)
295	{
296	  if (g_npets >= VELAPAW_MAX_PETS || samples == NULL || n_samples <= 0)
297	    {
298	      return VELAPAW_PET_UNKNOWN;
299	    }
300	
301	  struct velapaw_pet *p = &g_pets[g_npets];
302	
303	  p->id            = g_npets;
304	  p->portion_g     = portion_g;
305	  p->cooldown_s    = cooldown_s;
306	  p->daily_limit_g = daily_limit_g;
307	  p->samples_n     = n_samples;
308	  for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
309	    {
310	      p->meal_min[k] = meal_min ? meal_min[k] : -1;
311	    }
312	  vp_copy_name(p->name, VELAPAW_NAME_MAX, name);
313	
314	  /* Average the sample embeddings. */
315	  for (int d = 0; d < VELAPAW_EMBED_DIM; d++)
316	    {
317	      float acc = 0.0f;
318	      for (int s = 0; s < n_samples; s++)
319	        {
320	          acc += samples[s][d];
321	        }
322	
323	      p->embedding[d] = acc / (float)n_samples;
324	    }
325	
326	  /* Re-normalize the averaged centroid. */
327	  float norm = 0.0f;
328	  for (int d = 0; d < VELAPAW_EMBED_DIM; d++)
329	    {
330	      norm += p->embedding[d] * p->embedding[d];
331	    }
332	
333	  norm = sqrtf(norm);
334	  if (norm < 1e-6f)
335	    {
336	      norm = 1.0f;
337	    }
338	
339	  for (int d = 0; d < VELAPAW_EMBED_DIM; d++)
340	    {
341	      p->embedding[d] /= norm;
342	    }
343	
344	  return g_pets[g_npets++].id;
345	}
