347	/****************************************************************************
348	 * Name: velapaw_meal_norm
349	 *
350	 * Description:
351	 *   Fold a pet name to a comparison key: lower case, no leading or trailing
352	 *   whitespace, no trailing punctuation.  Deliberately avoids <ctype.h> so
353	 *   this file's include block does not have to change.
354	 *
355	 ****************************************************************************/
356	
357	static void velapaw_meal_norm(const char *in, char *out, int outsz)
358	{
359	  int n = 0;
360	
361	  if (out == NULL || outsz <= 0)
362	    {
363	      return;
364	    }
365	
366	  out[0] = '\0';
367	
368	  if (in == NULL)
369	    {
370	      return;
371	    }
372	
373	  while (*in == ' ' || *in == '\t')
374	    {
375	      in++;
376	    }
377	
378	  while (*in != '\0' && n < outsz - 1)
379	    {
380	      char c = *in++;
381	
382	      if (c >= 'A' && c <= 'Z')
383	        {
384	          c = (char)(c + ('a' - 'A'));
385	        }
386	
387	      out[n++] = c;
388	    }
389	
390	  /* Trim everything that is not a letter or digit off the tail. */
391	
392	  while (n > 0)
393	    {
394	      char c = out[n - 1];
395	
396	      if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))
397	        {
398	          break;
399	        }
400	
401	      n--;
402	    }
403	
404	  out[n] = '\0';
405	}
406	
407	int velapaw_meal_set_by_name(const char *name, int slot, int minute)
408	{
409	  char want[VELAPAW_NAME_MAX];
410	  char have[VELAPAW_NAME_MAX];
411	  int  meal[VELAPAW_MAX_MEALS];
412	  const struct velapaw_pet *p;
413	  int found = -1;
414	  int n;
415	  int k;
416	
417	  if (slot < 0 || slot >= VELAPAW_MAX_MEALS)
418	    {
419	      return -1;
420	    }
421	
422	  if (minute != -1 && (minute < 0 || minute > (23 * 60 + 59)))
423	    {
424	      return -1;
425	    }
426	
427	  velapaw_meal_norm(name, want, (int)sizeof(want));
428	
429	  if (want[0] == '\0')
430	    {
431	      return -1;
432	    }
433	
434	  n = velapaw_identity_count();
435	
436	  for (k = 0; k < n && k < VELAPAW_MAX_PETS; k++)
437	    {
438	      p = velapaw_identity_get((velapaw_pet_id_t)k);
439	
440	      if (p == NULL)
441	        {
442	          continue;
443	        }
444	
445	      velapaw_meal_norm(p->name, have, (int)sizeof(have));
446	
447	      if (strcmp(have, want) != 0)
448	        {
449	          continue;
450	        }
451	
452	      if (found >= 0)
453	        {
454	          return -3;              /* two pets answer to the same name */
455	        }
456	
457	      found = k;
458	    }
459	
460	  if (found < 0)
461	    {
462	      return -2;
463	    }
464	
465	  p = velapaw_identity_get((velapaw_pet_id_t)found);
466	
467	  if (p == NULL)
468	    {
469	      return -2;
470	    }
471	
472	  /* Copy all three slots.  velapaw_identity_update() writes every slot of the
473	   * array it is handed, so a partial array would silently switch the other
474	   * two meals off.
475	   */
476	
477	  for (k = 0; k < VELAPAW_MAX_MEALS; k++)
478	    {
479	      meal[k] = p->meal_min[k];
480	    }
481	
482	  meal[slot] = minute;
483	
484	  /* 0 for portion and limit means "leave alone": update() assigns those only
485	   * when the value is > 0.
486	   */
487	
488	  if (velapaw_identity_update((velapaw_pet_id_t)found, 0, 0, meal) < 0)
489	    {
490	      return -4;
491	    }
492	
493	  return velapaw_identity_save();
494	}
495	
496	int velapaw_identity_update(velapaw_pet_id_t id, int portion_g,
497	                            int daily_limit_g, const int *meal_min)
498	{
499	  if (id < 0 || id >= g_npets)
500	    {
501	      return -1;
502	    }
503	
504	  struct velapaw_pet *p = &g_pets[id];
505	
506	  if (portion_g > 0)
507	    {
508	      p->portion_g = portion_g;
509	    }
510	
511	  if (daily_limit_g > 0)
512	    {
513	      /* a limit below one serving would block every feed */
514	      p->daily_limit_g = (daily_limit_g < p->portion_g) ? p->portion_g
515	                                                        : daily_limit_g;
516	    }
517	
518	  if (meal_min != NULL)
519	    {
520	      for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
521	        {
522	          p->meal_min[k] = meal_min[k];
523	        }
524	    }
525	
526	  /* embedding / name / samples_n deliberately untouched: editing a schedule
527	   * must never disturb recognition. */
528	  return 0;
529	}
530	
531	int velapaw_identity_delete(velapaw_pet_id_t id)
532	{
533	  if (id < 0 || id >= g_npets)
534	    {
535	      return -1;
536	    }
537	
538	  /* Compact the array and renumber: ids are indices, so every pet after the
539	   * deleted one shifts down by one. Callers MUST shift their own per-pet
540	   * tables the same way or the data will belong to the wrong pet. */
541	  for (int i = id; i < g_npets - 1; i++)
542	    {
543	      g_pets[i]    = g_pets[i + 1];
544	      g_pets[i].id = i;
545	      memcpy(g_icon[i], g_icon[i + 1], sizeof(g_icon[0]));  /* icon follows pet */
546	      g_icon_valid[i] = g_icon_valid[i + 1];
547	    }
548	
549	  memset(&g_pets[g_npets - 1], 0, sizeof(g_pets[0]));
550	  g_icon_valid[g_npets - 1] = 0;
551	  g_npets--;
552	  printf("velapaw/identity: deleted pet %d, %d left\n", (int)id, g_npets);
553	  return 0;
554	}
555	
556	void velapaw_identity_match(const float *embedding, struct velapaw_match *out)
557	{
558	  if (out == NULL)
559	    {
560	      return;
561	    }
562	
563	  out->id     = VELAPAW_PET_UNKNOWN;
564	  out->score  = -1.0f;
565	  out->margin = 0.0f;
566	
567	  if (embedding == NULL || g_npets == 0)
568	    {
569	      return;
570	    }
571	
572	  float best = -1.0f;
573	  float second = -1.0f;
574	  velapaw_pet_id_t best_id = VELAPAW_PET_UNKNOWN;
575	
576	  for (int i = 0; i < g_npets; i++)
577	    {
578	      float dot = 0.0f;
579	      for (int d = 0; d < VELAPAW_EMBED_DIM; d++)
580	        {
581	          dot += embedding[d] * g_pets[i].embedding[d];
582	        }
583	
584	      if (dot > best)
585	        {
586	          second  = best;
587	          best    = dot;
588	          best_id = g_pets[i].id;
589	        }
590	      else if (dot > second)
591	        {
592	          second = dot;
593	        }
594	    }
595	
596	  out->score  = best;
597	  out->margin = (second > -1.0f) ? (best - second) : best;
598	
599	  if (best >= VELAPAW_MATCH_THRESHOLD)
600	    {
601	      out->id = best_id;
602	    }
603	}
