62	 *               the preview down while no pet is present (a cat lingers at the
63	 *               bowl for seconds, so 2 fps still catches it), and go back to
64	 *               full rate once one is on camera. ~4x fewer idle captures. */
65	#define FRAME_IDLE_MS      500    /* Recognize: preview rate while no pet seen */
66	#define ENROLL_IDLE_MS     30000  /* Enroll: pause preview after 30s untouched */
