1464	/* Delete a pet, keeping every per-pet table in step.
1465	 *
1466	 * Pet ids ARE array indices, so velapaw_identity_delete() renumbers every pet
1467	 * after the deleted one. Anything keyed by id must shift the same way or the
1468	 * data ends up on the wrong animal: the feeding history (store), the meal
1469	 * timeline tables here, and any id we're currently holding. */
1470	static void do_delete_pet(velapaw_pet_id_t id)
1471	{
1472	  int n = velapaw_identity_count();
1473	  int p, k;
1474	
1475	  if (id < 0 || id >= n)
1476	    {
1477	      return;
1478	    }
1479	
1480	  /* shift this file's per-pet tables down over the deleted slot */
1481	  for (p = id; p < VELAPAW_MAX_PETS - 1; p++)
1482	    {
1483	      for (k = 0; k < VELAPAW_MAX_MEALS; k++)
1484	        {
1485	          g_meal_fed_day[p][k] = g_meal_fed_day[p + 1][k];
1486	          g_meal_fed_min[p][k] = g_meal_fed_min[p + 1][k];
1487	          g_meal_fed_g[p][k]   = g_meal_fed_g[p + 1][k];
1488	          g_meal_skipped[p][k] = g_meal_skipped[p + 1][k];
1489	        }
1490	      g_last_fed[p] = g_last_fed[p + 1];
1491	    }
1492	  for (k = 0; k < VELAPAW_MAX_MEALS; k++)
1493	    {
1494	      g_meal_fed_day[VELAPAW_MAX_PETS - 1][k] = 0;   /* 0 = never fed */
1495	      g_meal_fed_min[VELAPAW_MAX_PETS - 1][k] = 0;
1496	      g_meal_fed_g[VELAPAW_MAX_PETS - 1][k]   = 0;
1497	      g_meal_skipped[VELAPAW_MAX_PETS - 1][k] = 0;
1498	    }
1499	  g_last_fed[VELAPAW_MAX_PETS - 1] = 0;
1500	
1501	  velapaw_store_delete(id);            /* history + BCS, shifted to match */
1502	  velapaw_identity_delete(id);         /* the pet itself + icon, renumbers rest */
1503	  velapaw_identity_save();             /* persist: stays deleted after reset */
1504	  velapaw_identity_save_icons();       /* icons were shifted too */
1505	
1506	  /* every id we were holding may now point at a different pet */
1507	  g_fed_visit = VELAPAW_PET_UNKNOWN;
1508	  g_bcs_for   = VELAPAW_PET_UNKNOWN;
1509	  g_cand      = VELAPAW_PET_UNKNOWN;
1510	  g_stable    = 0;
1511	
1512	  n = velapaw_identity_count();
1513	  if (g_trend_pet >= n) g_trend_pet = (n > 0) ? n - 1 : 0;
1514	  g_petn = n;
1515	
1516	  printf("velapaw/ui: deleted pet %d (%d left)\n", (int)id, n);
1517	}
