1534	static void refresh_pets(void)
1535	{
1536	  if (g_pets_box == NULL)
1537	    {
1538	      return;
1539	    }
1540	  lv_obj_clean(g_pets_box);
1541	  int n = velapaw_identity_count();
1542	  if (n == 0)
1543	    {
1544	      lv_obj_t *l = make_label(g_pets_box, F_BODY, COL_DIM);
1545	      lv_label_set_text(l, T(S_NO_PETS));
1546	      update_bell();
1547	      return;
1548	    }
1549	  for (int i = 0; i < n; i++)
1550	    {
1551	      const struct velapaw_pet *p = velapaw_identity_get(i);
1552	      int today = velapaw_store_today_total(i);
1553	      int meals = velapaw_store_today_meals(i);
1554	      int avg   = velapaw_store_baseline_g(i);
1555	      int week  = velapaw_store_week_total(i);
