1558	
1559	      lv_obj_t *row = make_card(g_pets_box, COL_W - 8, LV_SIZE_CONTENT, COL_CARD2);
1560	      lv_obj_set_flex_flow(row, LV_FLEX_FLOW_COLUMN);
1561	      lv_obj_set_style_pad_row(row, 2, 0);
1562	
1563	      /* header: [icon | name]. Icon is the enrolled thumbnail, or a coloured
1564	       * disc with the pet's initial if this pet predates the icon feature. */
1565	      lv_obj_t *hdr = lv_obj_create(row);
1566	      lv_obj_set_size(hdr, lv_pct(100), 52);
1567	      lv_obj_set_style_bg_opa(hdr, LV_OPA_TRANSP, 0);
1568	      lv_obj_set_style_border_width(hdr, 0, 0);
1569	      lv_obj_set_style_pad_all(hdr, 0, 0);
1570	      lv_obj_clear_flag(hdr, LV_OBJ_FLAG_SCROLLABLE);
1571	      lv_obj_set_flex_flow(hdr, LV_FLEX_FLOW_ROW);
1572	      lv_obj_set_flex_align(hdr, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
1573	                            LV_FLEX_ALIGN_CENTER);
1574	      lv_obj_set_style_pad_column(hdr, 12, 0);
1575	
1576	      const uint16_t *ic = velapaw_identity_get_icon(i);
1577	      if (ic)
1578	        {
1579	          g_petcard_dsc[i].header.cf   = LV_COLOR_FORMAT_RGB565;
1580	          g_petcard_dsc[i].header.w    = VELAPAW_ICON_W;
1581	          g_petcard_dsc[i].header.h    = VELAPAW_ICON_H;
1582	          g_petcard_dsc[i].data_size   = VELAPAW_ICON_W * VELAPAW_ICON_H * 2;
1583	          g_petcard_dsc[i].data        = (const uint8_t *)ic;
1584	          /* circular frame that clips the photo to a disc, matching the "K"
1585	           * placeholder's shape */
1586	          lv_obj_t *frame = lv_obj_create(hdr);
1587	          lv_obj_set_size(frame, VELAPAW_ICON_W, VELAPAW_ICON_H);
1588	          lv_obj_set_style_radius(frame, LV_RADIUS_CIRCLE, 0);
1589	          lv_obj_set_style_clip_corner(frame, true, 0);
1590	          lv_obj_set_style_border_width(frame, 0, 0);
1591	          lv_obj_set_style_pad_all(frame, 0, 0);
1592	          lv_obj_clear_flag(frame, LV_OBJ_FLAG_SCROLLABLE);
1593	          lv_obj_t *img = lv_image_create(frame);
1594	          lv_image_set_src(img, &g_petcard_dsc[i]);
1595	          lv_obj_center(img);
1596	        }
1597	      else
1598	        {
1599	          lv_obj_t *disc = lv_obj_create(hdr);
1600	          lv_obj_set_size(disc, VELAPAW_ICON_W, VELAPAW_ICON_H);
1601	          lv_obj_set_style_radius(disc, LV_RADIUS_CIRCLE, 0);
1602	          lv_obj_set_style_bg_color(disc, lv_color_hex(COL_BTN), 0);
1603	          lv_obj_set_style_border_width(disc, 0, 0);
1604	          lv_obj_clear_flag(disc, LV_OBJ_FLAG_SCROLLABLE);
1605	          lv_obj_t *ini = lv_label_create(disc);
1606	          char c[2] = { p->name[0] ? p->name[0] : '?', 0 };
1607	          lv_label_set_text(ini, c);
1608	          lv_obj_set_style_text_font(ini, F_HEAD, 0);
1609	          lv_obj_set_style_text_color(ini, lv_color_hex(COL_ACCENT), 0);
1610	          lv_obj_center(ini);
1611	        }
1612	
1613	      lv_obj_t *nm = make_label(hdr, F_HEAD, COL_TEXT);
1614	      lv_label_set_text(nm, p->name);
1615	
1616	      lv_obj_t *l1 = make_label(row, F_SMALL,
1617	                                (today >= p->daily_limit_g) ? COL_FED : COL_DIM);
1618	      lv_label_set_text_fmt(l1, T(S_TODAY_FMT),
1619	                            today, p->daily_limit_g, meals);
1620	      if (today >= p->daily_limit_g)
1621	        {
1622	          lv_obj_t *lim = make_label(row, F_SMALL, COL_FED);
1623	          lv_label_set_text(lim, T(S_LIMIT_REACHED));
1624	        }
1625	
1626	      /* ---- meal timeline: what was scheduled vs what actually happened ----
1627	       * "08:00  ate 08:02  15g"  = eaten (recognised at/after the meal)
1628	       * "12:30  waiting for pet" = meal is due but the pet hasn't shown up
1629	       * "18:00  pending"         = still ahead today
1630	       * "18:00  skipped"         = owner tapped it off; won't dispense today
1631	       * Not-yet-eaten rows are tappable to toggle skipped, e.g. skip meal 2
1632	       * but still feed 1 and 3. Resets automatically at the next Next Day. */
1633	      { long today_d = wall_day();
1634	        int  nowm    = wall_min();
1635	        int  any     = 0;
1636	        for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
1637	          {
1638	            int mm = p->meal_min[k];
1639	            if (mm < 0) continue;
1640	            any = 1;
1641	            lv_obj_t *ml = make_label(row, F_SMALL, COL_DIM);
