1645	                lv_label_set_text_fmt(ml, T(S_ATE_FMT),
1646	                    mm / 60, mm % 60,
1647	                    g_meal_fed_min[i][k] / 60, g_meal_fed_min[i][k] % 60,
1648	                    g_meal_fed_g[i][k]);
1649	              }
1650	            else
1651	              {
1652	                lv_obj_add_flag(ml, LV_OBJ_FLAG_CLICKABLE);
1653	                lv_obj_set_ext_click_area(ml, 10);
1654	                lv_obj_add_event_cb(ml, meal_skip_toggle_cb, LV_EVENT_CLICKED,
1655	                    (void *)(intptr_t)(i * VELAPAW_MAX_MEALS + k));
1656	                if (g_meal_skipped[i][k])
1657	                  {
1658	                    lv_label_set_text_fmt(ml, T(S_SKIPPED), mm / 60, mm % 60);
1659	                  }
1660	                else if (nowm >= mm)
1661	                  {
1662	                    lv_obj_set_style_text_color(ml, lv_color_hex(COL_COOL), 0);
1663	                    lv_label_set_text_fmt(ml, T(S_WAITING), mm / 60, mm % 60);
1664	                  }
1665	                else
1666	                  {
1667	                    lv_label_set_text_fmt(ml, T(S_PENDING), mm / 60, mm % 60);
1668	                  }
1669	              }
1670	          }
1671	        if (!any)
1672	          {
1673	            lv_obj_t *ml = make_label(row, F_SMALL, COL_DIM);
1674	            lv_label_set_text(ml, T(S_NO_MEALS_SCHED));
1675	          } }
1676	
1677	      lv_obj_t *l2 = make_label(row, F_SMALL, COL_DIM);
1678	      lv_label_set_text_fmt(l2, T(S_AVG_WEEK_FMT), avg, week);
1679	
1680	      uint32_t pcol = (pct >= 70) ? COL_FED : (pct >= 40) ? COL_COOL : COL_UNK;
1681	      lv_obj_t *l3 = make_label(row, F_BODY, pcol);
1682	      if (alert)
1683	        {
1684	          lv_label_set_text_fmt(l3, T(S_APPETITE_DROP_FMT), pct);
1685	        }
1686	      else
1687	        {
1688	          lv_label_set_text_fmt(l3, T(S_APPETITE_FMT), pct);
1689	        }
1690	
1691	      /* Body Condition Score from the 2nd on-device model */
1692	      int bcs = velapaw_store_get_bcs(i);
1693	      const char *bnm = (bcs == 0) ? T(S_BCS_UNDER) : (bcs == 1) ? T(S_BCS_IDEAL)
1694	                        : (bcs == 2) ? T(S_BCS_OVER) : T(S_BCS_NA);
1695	      uint32_t bcol = (bcs == 1) ? COL_FED : (bcs < 0) ? COL_DIM : COL_COOL;
1696	      lv_obj_t *l4 = make_label(row, F_BODY, bcol);
