1698	        {
1699	          lv_label_set_text_fmt(l4, T(S_BCS_VET_FMT), bnm);
1700	        }
1701	      else
1702	        {
1703	          lv_label_set_text_fmt(l4, T(S_BCS_FMT), bnm);
1704	        }
1705	
1706	      /* 7-day intake sparkline (oldest -> today) */
1707	      lv_obj_t *spark = lv_obj_create(row);
1708	      lv_obj_set_size(spark, COL_W - 60, 36);
1709	      lv_obj_set_style_bg_opa(spark, LV_OPA_TRANSP, 0);
1710	      lv_obj_set_style_border_width(spark, 0, 0);
1711	      lv_obj_set_style_pad_all(spark, 0, 0);
1712	      lv_obj_clear_flag(spark, LV_OBJ_FLAG_SCROLLABLE);
1713	      lv_obj_set_flex_flow(spark, LV_FLEX_FLOW_ROW);
1714	      lv_obj_set_flex_align(spark, LV_FLEX_ALIGN_SPACE_EVENLY,
