1732	          lv_obj_set_style_pad_all(bar, 0, 0);
1733	          lv_obj_clear_flag(bar, LV_OBJ_FLAG_SCROLLABLE);
1734	          lv_obj_set_style_bg_color(bar,
1735	              lv_color_hex(d == 0 ? COL_ACCENT : COL_BTN), 0);
1736	        }
1737	
1738	      /* Change this pet's meal times / portion without re-enrolling it. */
1739	      lv_obj_t *eb = lv_button_create(row);
1740	      lv_obj_set_size(eb, 180, 34);
1741	      lv_obj_set_style_bg_color(eb, lv_color_hex(COL_BTN), 0);
