3411	/* Build (or rebuild) the whole UI tree onto g_scr in the CURRENT language.
3412	 * Called once at startup, then again on every language toggle. The pipeline
3413	 * (camera/backend/store/identity) is already running by then and is NOT touched
3414	 * here -- only the LVGL widget tree is torn down and recreated, which is how the
3415	 * one-shot labels pick up the new language + font. */
3416	static void ui_build(void)
3417	{
3418	#ifdef CONFIG_VELAPAW_VOICE
3419	  /* Every widget this dialog writes to is about to be freed.  Stop it BEFORE
3420	   * the clean, not after: vsched_stop() would repaint a dangling label. */
3421	
3422	  g_vs.state = VS_IDLE;
3423	  g_vc_lbl   = NULL;
3424	  g_vc_btn   = NULL;
3425	#endif
3426	
3427	  lv_obj_clean(lv_layer_top());        /* drop the old keyboard / modal / popups */
3428	  lv_obj_clean(g_scr);                 /* drop the old root and every tab         */
3429	
3430	  /* full-screen root */
3431	  lv_obj_t *col = lv_obj_create(g_scr);
3432	  lv_obj_set_size(col, SCR_W, SCR_H);
3433	  lv_obj_align(col, LV_ALIGN_CENTER, 0, 0);
3434	  lv_obj_set_style_bg_color(col, lv_color_hex(COL_BG), 0);
3435	  lv_obj_set_style_border_width(col, 0, 0);
3436	  lv_obj_set_style_pad_all(col, 0, 0);
3437	  lv_obj_set_style_radius(col, 0, 0);
3438	  lv_obj_clear_flag(col, LV_OBJ_FLAG_SCROLLABLE);
3439	
3440	  /* slim header: breadcrumb + language toggle + bell */
3441	  lv_obj_t *hdr = lv_obj_create(col);
