68	/* Runs on the internal-RAM-stack thread: flash erase/write suspend the cache,
69	 * so none of this may execute on the velapaw task's PSRAM stack. */
70	static void *pet_flash_thread(void *arg)
71	{
72	  struct pet_io *io = (struct pet_io *)arg;
73	
74	  if (io->write)
75	    {
76	      io->rc = spi_flash_erase_range(VELAPAW_PET_FLASH_OFF, PET_AREA_BYTES);
77	      if (io->rc >= 0)
78	        {
79	          io->rc = spi_flash_write(VELAPAW_PET_FLASH_OFF, &g_hdr, sizeof(g_hdr));
80	        }
81	      if (io->rc >= 0)
82	        {
83	          io->rc = spi_flash_write(VELAPAW_PET_FLASH_OFF + PET_HDR_RESERVED,
84	                                   g_pets, sizeof(g_pets));
85	        }
86	    }
87	  else
88	    {
89	      io->rc = spi_flash_read(VELAPAW_PET_FLASH_OFF, &g_hdr, sizeof(g_hdr));
90	      if (io->rc >= 0 &&
91	          g_hdr.magic   == VELAPAW_PET_MAGIC &&
92	          g_hdr.version == VELAPAW_PET_VERSION &&
93	          g_hdr.npets   <= VELAPAW_MAX_PETS)
94	        {
95	          /* header is good -> only now do we overwrite g_pets */
96	          io->rc = spi_flash_read(VELAPAW_PET_FLASH_OFF + PET_HDR_RESERVED,
97	                                  g_pets, sizeof(g_pets));
98	        }
99	      else
100	        {
101	          io->rc = -1;                            /* blank/garbage -> no pets */
102	        }
103	    }
104	  return NULL;
105	}
106	
107	static int pet_flash_run(int write)
108	{
109	  struct pet_io io = { write, -1 };
110	  pthread_attr_t attr;
111	  pthread_t th;
112	  pthread_attr_init(&attr);
113	  pthread_attr_setstack(&attr, g_pet_flash_stack, sizeof(g_pet_flash_stack));
114	  if (pthread_create(&th, &attr, pet_flash_thread, &io) != 0)
115	    {
116	      pthread_attr_destroy(&attr);
117	      return -1;
118	    }
119	  pthread_join(th, NULL);
120	  pthread_attr_destroy(&attr);
121	  return io.rc;
122	}
