240	/* ---- wall clock -----------------------------------------------------------
241	 * Software CLOCK_REALTIME (no hardware RTC: enabling it killed the USB console,
242	 * so the clock is set by the user each session via Set Clock and starts at a
243	 * sane default). LOCALTIME is off, so derive HH:MM straight from epoch seconds
244	 * and treat that as local time. */
245	static int wall_min(void)          /* minute-of-day, 0..1439 */
246	{
247	  struct timespec ts;
248	  clock_gettime(CLOCK_REALTIME, &ts);
249	  return (int)((ts.tv_sec % 86400) / 60);
250	}
251	static long wall_day(void)         /* day number (for per-day "fed" resets) */
252	{
253	  struct timespec ts;
254	  clock_gettime(CLOCK_REALTIME, &ts);
255	  return (long)(ts.tv_sec / 86400);
256	}
257	/* Board hook: persist the clock into the on-board PCF85063 RTC chip (direct
258	 * I2C in the board file). Weak-ish: returns <0 if the chip isn't there. */
259	extern int board_rtc_settime(time_t t);
260	
261	static void wall_set_min(int minofday)   /* set clock to today at HH:MM */
262	{
263	  struct timespec ts;
264	  clock_gettime(CLOCK_REALTIME, &ts);
265	  if (minofday < 0) minofday += 1440;
266	  minofday %= 1440;
267	  ts.tv_sec  = (ts.tv_sec / 86400) * 86400 + (long)minofday * 60;
268	  ts.tv_nsec = 0;
269	  clock_settime(CLOCK_REALTIME, &ts);
270	  board_rtc_settime(ts.tv_sec);   /* survive reset / power-off */
271	}
