3525	               (s[2] & 0xc0) == 0x80)
3526	        {
3527	          len = 3;
3528	          if (c == 0xe2 && s[1] == 0x80)
3529	            {
3530	              switch (s[2])
3531	                {
3532	                  case 0x98: case 0x99: rep = "'";   break;  /* U+2018/9 */
3533	                  case 0x9c: case 0x9d: rep = "\"";  break;  /* U+201C/D */
3534	                  case 0x93: case 0x94: rep = "-";   break;  /* U+2013/4 */
3535	                  case 0xa6:            rep = "..."; break;  /* U+2026   */
3536	                  default:                           break;
3537	                }
3538	            }
3539	        }
3540	      else
3541	        {
3542	          /* emoji or a broken sequence: skip it and its continuation bytes */
3543	
3544	          s++;
3545	          while ((*s & 0xc0) == 0x80)
3546	            {
3547	              s++;
3548	            }
3549	
3550	          continue;
3551	        }
3552	
3553	      size_t olen = rep ? strlen(rep) : len;
3554	
3555	      if (n + (sp ? 1 : 0) + olen > cap - 4)          /* room for "..." + NUL */
3556	        {
3557	          cut = 1;
3558	          break;
3559	        }
3560	
3561	      if (sp)
3562	        {
3563	          dst[n++] = ' ';
3564	          sp = 0;
3565	        }
3566	
3567	      memcpy(dst + n, rep ? rep : (const char *)s, olen);
3568	      n += olen;
3569	      s += len;
3570	    }
3571	
3572	  if (cut)
3573	    {
3574	      memcpy(dst + n, "...", 3);
3575	      n += 3;
3576	    }
3577	
3578	  dst[n] = '\0';
3579	}
