3581	/* Called on the ai_agent thread from packages/ai_agent/src/core/agent_loop.c,
3582	 * which declares it by hand (same FLAT image).  kind: 0 = turn started (text is
3583	 * the question), 1 = reply, 2 = failed, 3 = tools ran but the confirming LLM
3584	 * call timed out.  Copies only; the caller keeps ownership of `text`. */
3585	void velapaw_agent_event(const char *chat_id, const char *text, int kind);
3586	
3587	void velapaw_agent_event(const char *chat_id, const char *text, int kind)
3588	{
3589	  pthread_mutex_lock(&g_ag_lock);
3590	
3591	  g_ag_in_hb = (chat_id != NULL && strcmp(chat_id, "heartbeat") == 0);
3592	  g_ag_in_ok = 0;
3593	
3594	  switch (kind)
3595	    {
3596	      case 0:
3597	        ag_clean(g_ag_in_q, sizeof(g_ag_in_q), text);
3598	        g_ag_in_a[0]  = '\0';
3599	        g_ag_in_state = AG_WORKING;
3600	        break;
3601	
3602	      case 1:
3603	        ag_clean(g_ag_in_a, sizeof(g_ag_in_a), text);
3604	        g_ag_in_ok    = (text != NULL && strstr(text, "HEARTBEAT_OK") != NULL);
3605	        g_ag_in_state = AG_REPLIED;
3606	        break;
3607	
3608	      case 3:
3609	        g_ag_in_a[0]  = '\0';
3610	        g_ag_in_state = AG_DONE;
3611	        break;
3612	
3613	      default:
3614	        g_ag_in_a[0]  = '\0';
3615	        g_ag_in_state = AG_FAILED;
3616	        break;
3617	    }
3618	
3619	  g_ag_seq++;
3620	  pthread_mutex_unlock(&g_ag_lock);
3621	}
