3623	/* Paint the toast from the UI-thread copy of the agent state. */
3624	static void ag_render(long now)
3625	{
3626	  uint32_t edge = COL_ACCENT;
3627	  uint32_t ink  = COL_TEXT;
3628	
3629	  if (g_ag_toast == NULL || g_ag_state == AG_IDLE)
3630	    {
3631	      return;
3632	    }
3633	
3634	  if (g_ag_hb)
3635	    {
3636	      lv_obj_add_flag(g_ag_ql, LV_OBJ_FLAG_HIDDEN);
3637	    }
3638	  else
3639	    {
3640	      lv_obj_clear_flag(g_ag_ql, LV_OBJ_FLAG_HIDDEN);
3641	      lv_label_set_text_fmt(g_ag_ql, T(S_AG_YOU_FMT), g_ag_q);
3642	    }
3643	
3644	  switch (g_ag_state)
3645	    {
3646	      case AG_WORKING:
3647	        ink = COL_ACCENT;
3648	        if (g_ag_hb)
3649	          {
3650	            lv_label_set_text(g_ag_al, T(S_AG_CHECKING));
3651	          }
3652	        else
3653	          {
3654	            g_ag_last_s = (int)((now - g_ag_t0) / 1000);
3655	            lv_label_set_text_fmt(g_ag_al, T(S_AG_WORKING_FMT), g_ag_last_s);
3656	          }
3657	        break;
3658	
3659	      case AG_REPLIED:
3660	        if (g_ag_hb && g_ag_ok)
3661	          {
3662	            edge = ink = COL_FED;
3663	            lv_label_set_text_fmt(g_ag_al, T(S_AG_HB_OK_FMT),
3664	                                  g_ag_min / 60, g_ag_min % 60);
3665	          }
3666	        else if (g_ag_hb)
3667	          {
3668	            edge = ink = COL_UNK;
3669	            lv_label_set_text_fmt(g_ag_al, T(S_AG_WARN_FMT),
3670	                                  g_ag_min / 60, g_ag_min % 60, g_ag_a);
3671	          }
3672	        else
3673	          {
3674	            lv_label_set_text_fmt(g_ag_al, T(S_AG_REPLY_FMT), g_ag_a);
3675	          }
3676	        break;
3677	
3678	      case AG_DONE:
3679	        edge = ink = COL_FED;
3680	        lv_label_set_text(g_ag_al, T(S_AG_DONE));
3681	        break;
3682	
3683	      default:
3684	        edge = ink = COL_COOL;
3685	        lv_label_set_text(g_ag_al, T(S_AG_FAILED));
3686	        break;
3687	    }
3688	
3689	  lv_obj_set_style_border_color(g_ag_toast, lv_color_hex(edge), 0);
3690	  lv_obj_set_style_text_color(g_ag_al, lv_color_hex(ink), 0);
3691	
3692	  if (g_ag_shown)
3693	    {
3694	      lv_obj_clear_flag(g_ag_toast, LV_OBJ_FLAG_HIDDEN);
3695	    }
3696	  else
3697	    {
3698	      lv_obj_add_flag(g_ag_toast, LV_OBJ_FLAG_HIDDEN);
3699	    }
3700	}
