3739	static void ag_poll(long now)
3740	{
3741	  if (g_ag_seq != g_ag_seen)
3742	    {
3743	      pthread_mutex_lock(&g_ag_lock);
3744	      g_ag_seen  = g_ag_seq;           /* newest wins; a start+reply pair that
3745	                                        * lands in one 20 ms pass shows as the
3746	                                        * reply, with its question */
3747	      g_ag_state = g_ag_in_state;
3748	      g_ag_hb    = g_ag_in_hb;
3749	      g_ag_ok    = g_ag_in_ok;
3750	      memcpy(g_ag_q, g_ag_in_q, sizeof(g_ag_q));
3751	      memcpy(g_ag_a, g_ag_in_a, sizeof(g_ag_a));
3752	      pthread_mutex_unlock(&g_ag_lock);
3753	
3754	      g_ag_t0      = now;
3755	      g_ag_hide_at = 0;
3756	      g_ag_last_s  = -1;
3757	
3758	      if (g_ag_hb && g_ag_state == AG_REPLIED)
3759	        {
3760	          g_ag_min   = wall_min();
3761	          g_ag_alert = !g_ag_ok;
3762	          if (g_ag_ok)
3763	            {
3764	              g_ag_hide_at = now + AG_OK_SHOW_MS;
3765	            }
3766	          else
3767	            {
3768	              memcpy(g_ag_txt, g_ag_a, sizeof(g_ag_txt));
3769	            }
3770	
3771	          update_bell();
3772	        }
3773	      else if (g_ag_hb && g_ag_state != AG_WORKING)
3774	        {
3775	          g_ag_state = AG_IDLE;        /* a failed heartbeat is not news */
3776	        }
3777	      else if (g_ag_state != AG_WORKING)
3778	        {
3779	          g_ag_hide_at = now + AG_REPLY_SHOW_MS;
3780	        }
3781	
3782	      g_ag_shown = (g_ag_state != AG_IDLE);
3783	      if (g_ag_toast != NULL && !g_ag_shown)
3784	        {
3785	          lv_obj_add_flag(g_ag_toast, LV_OBJ_FLAG_HIDDEN);
3786	        }
3787	
3788	      ag_render(now);
3789	    }
3790	  else if (g_ag_state == AG_WORKING)
3791	    {
3792	      if (now - g_ag_t0 > AG_STUCK_MS)
3793	        {
3794	          /* no end-of-turn ever came (a path in agent_loop that drops the
3795	           * message without replying): stop counting forever */
3796	
3797	          g_ag_state   = g_ag_hb ? AG_IDLE : AG_FAILED;
3798	          g_ag_shown   = (g_ag_state != AG_IDLE);
3799	          g_ag_hide_at = now + AG_REPLY_SHOW_MS;
3800	          if (g_ag_toast != NULL && !g_ag_shown)
3801	            {
3802	              lv_obj_add_flag(g_ag_toast, LV_OBJ_FLAG_HIDDEN);
3803	            }
3804	
3805	          ag_render(now);
3806	        }
3807	      else if (!g_ag_hb && (int)((now - g_ag_t0) / 1000) != g_ag_last_s)
3808	        {
3809	          ag_render(now);
3810	        }
3811	    }
3812	
3813	  if (g_ag_hide_at != 0 && now >= g_ag_hide_at)
3814	    {
3815	      g_ag_hide_at = 0;
3816	      g_ag_shown   = 0;
3817	      if (g_ag_toast != NULL)
3818	        {
3819	          lv_obj_add_flag(g_ag_toast, LV_OBJ_FLAG_HIDDEN);
3820	        }
3821	    }
3822	}
