3824	/* The agent's set_meal tool rewrites a pet from its own thread.  When it has,
3825	 * redraw My Pets, and fold the change into an open Edit dialog so a later Save
3826	 * cannot quietly put the old time back.  A slot the owner (or the voice
3827	 * dialog) already changed in the dialog keeps that value. */
3828	static void ident_poll(void)
3829	{
3830	  unsigned gen = velapaw_identity_gen();
3831	
3832	  if (gen == g_ident_seen)
3833	    {
3834	      return;
3835	    }
3836	
3837	  g_ident_seen = gen;
3838	
3839	  if (g_edit_pet >= 0)
3840	    {
3841	      const struct velapaw_pet *p = velapaw_identity_get(g_edit_pet);
3842	
3843	      if (p != NULL)
3844	        {
3845	          for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
3846	            {
3847	              if (g_edit_meal[k] == g_edit_orig[k])
3848	                {
3849	                  g_edit_meal[k] = p->meal_min[k];
3850	                }
3851	
3852	              g_edit_orig[k] = p->meal_min[k];
3853	            }
3854	
3855	          refresh_edit();
3856	        }
3857	    }
3858	
3859	  refresh_pets();
3860	}
