40	int tool_meal_set_execute(const char *input_json, char *output,
41	                          size_t output_size)
42	{
43	  cJSON *root = cJSON_Parse(input_json);
44	
45	  if (!root) {
46	      snprintf(output, output_size, "Error: invalid JSON input");
47	      return ERROR;
48	  }
49	
50	  /* Accept the three field names models actually emit for the pet. */
51	  const char *pet = cJSON_GetStringValue(cJSON_GetObjectItem(root, "pet"));
52	  if (!pet) pet = cJSON_GetStringValue(cJSON_GetObjectItem(root, "pet_name"));
53	  if (!pet) pet = cJSON_GetStringValue(cJSON_GetObjectItem(root, "name"));
54	
55	  cJSON *jslot = cJSON_GetObjectItem(root, "slot");
56	  if (!cJSON_IsNumber(jslot)) jslot = cJSON_GetObjectItem(root, "meal");
57	
58	  const char *tstr = cJSON_GetStringValue(cJSON_GetObjectItem(root, "time"));
59	  cJSON *jhour = cJSON_GetObjectItem(root, "hour");
60	  cJSON *jmin  = cJSON_GetObjectItem(root, "minute");
61	
62	  if (!pet || !cJSON_IsNumber(jslot)) {
63	      snprintf(output, output_size, "%s", MEAL_USAGE);
64	      cJSON_Delete(root);
65	      return ERROR;
66	  }
67	
68	  int slot = jslot->valueint;          /* owner-facing 1..3 */
69	  int minute;
70	
71	  if (meal_is_off(tstr)) {
72	      minute = -1;
73	  }
74	  else if (tstr != NULL) {
75	      int hh = -1, mm = 0;
76	      if (sscanf(tstr, "%d:%d", &hh, &mm) < 1 ||
77	          hh < 0 || hh > 23 || mm < 0 || mm > 59) {
78	          snprintf(output, output_size, "%s", MEAL_USAGE);
79	          cJSON_Delete(root);
80	          return ERROR;
81	      }
82	      minute = hh * 60 + mm;
83	  }
84	  else if (cJSON_IsNumber(jhour)) {
85	      int hh = jhour->valueint;
86	      int mm = cJSON_IsNumber(jmin) ? jmin->valueint : 0;
87	      if (hh < 0 || hh > 23 || mm < 0 || mm > 59) {
88	          snprintf(output, output_size, "%s", MEAL_USAGE);
89	          cJSON_Delete(root);
90	          return ERROR;
91	      }
92	      minute = hh * 60 + mm;
93	  }
94	  else {
95	      snprintf(output, output_size, "%s", MEAL_USAGE);
96	      cJSON_Delete(root);
97	      return ERROR;
98	  }
99	
100	  /* `pet` points INTO the cJSON tree, and every branch of the switch below
101	   * formats it -- but the tree is freed before the switch runs.  Reading it
102	   * after cJSON_Delete() is a use-after-free that put raw heap bytes into the
103	   * tool result, which made DeepSeek reject the WHOLE request with
104	   *   HTTP 400 ... messages[N].content: invalid unicode code point
105	   * while the flash write had already succeeded, so a working action reported
106	   * "Sorry, I encountered an error" (2026-10-11).  Copy the name first and
107	   * repoint `pet` at the copy, so all six branches below are safe.
108	   */
109	
110	  char petbuf[64];
111	  strncpy(petbuf, pet, sizeof(petbuf) - 1);
112	  petbuf[sizeof(petbuf) - 1] = '\0';
113	  pet = petbuf;
114	
115	  int rc = velapaw_meal_set_by_name(pet, slot - 1, minute);
116	  cJSON_Delete(root);
117	
118	  switch (rc) {
119	    case 0:
120	      if (minute < 0) {
121	          snprintf(output, output_size,
122	                   "Meal %d for %s is now off.", slot, pet);
123	      }
124	      else {
125	          /* State the Model-B gate explicitly: without it the model tells the
126	           * owner food appears at that time regardless, which is wrong. */
127	          snprintf(output, output_size,
128	                   "Meal %d for %s is set to %02d:%02d and saved to flash. "
129	                   "The feeder dispenses it only when %s is recognised at the "
130	                   "bowl at or after that time, once per day.",
131	                   slot, pet, minute / 60, minute % 60, pet);
132	      }
133	      return OK;
134	
135	    case -1:
136	      snprintf(output, output_size, "%s", MEAL_USAGE);
137	      return ERROR;
138	
139	    case -2:
140	      snprintf(output, output_size,
141	               "Error: no enrolled pet matches \"%s\". Read "
142	               "/data/ai_agent/velapaw/status.md for the enrolled names, then "
143	               "retry with one of them.", pet);
144	      return ERROR;
145	
146	    case -3:
147	      snprintf(output, output_size,
148	               "Error: more than one enrolled pet is called \"%s\". Ask the "
149	               "owner which one they mean.", pet);
150	      return ERROR;
151	
152	    case -4:
153	      snprintf(output, output_size,
154	               "Error: the feeder rejected the update for \"%s\".", pet);
155	      return ERROR;
156	
157	    default:
158	      snprintf(output, output_size,
159	               "Warning: meal %d for %s was changed in memory but could NOT be "
160	               "saved to flash (rc %d), so it will be lost on reboot. Tell the "
161	               "owner.", slot, pet, rc);
162	      return ERROR;
163	  }
164	}
