310	/****************************************************************************
311	 * Day stamping
312	 *
313	 * The window is an array whose last slot is "today", so something has to
314	 * move it.  Until now the only thing that did was the EV_NEXTDAY demo
315	 * button, which means a board left running past midnight kept adding to the
316	 * same slot for ever.  Over-reporting intake makes the feeder withhold real
317	 * meals, so this is the dangerous direction to get wrong.
318	 ****************************************************************************/
319	
320	static long vp_days_from_civil(int y, unsigned m, unsigned d)
321	{
322	  /* Exact day number across month and year boundaries.  tm_yday alone is
323	   * not enough: 12-31 -> 01-01 has to be a delta of 1, not -364.
324	   */
325	  y -= m <= 2;
326	  long era = (y >= 0 ? y : y - 399) / 400;
327	  unsigned yoe = (unsigned)(y - era * 400);
328	  unsigned doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
329	  unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
330	  return era * 146097 + (long)doe - 719468;
331	}
332	
333	static long vp_today_num(void)
334	{
335	  time_t now = time(NULL);
336	  struct tm tmv;
337	
338	  /* Same sanity floor the feed log uses: an unset clock must never be
339	   * allowed to shift real history.
340	   */
341	  if (now < VP_TS_SANE)
342	    {
343	      return -1;
344	    }
345	
346	  localtime_r(&now, &tmv);
347	  return vp_days_from_civil(tmv.tm_year + 1900, tmv.tm_mon + 1, tmv.tm_mday);
348	}
