350	static void vp_shift_days(int n)
351	{
352	  if (n <= 0)
353	    {
354	      return;
355	    }
356	
357	  if (n > DAYS)
358	    {
359	      n = DAYS;
360	    }
361	
362	  for (int p = 0; p < VELAPAW_MAX_PETS; p++)
363	    {
364	      int d = 0;
365	      for (; d < DAYS - n; d++)
366	        {
367	          g_day_g[p][d] = g_day_g[p][d + n];
368	          g_day_m[p][d] = g_day_m[p][d + n];
369	        }
370	
371	      for (; d < DAYS; d++)
372	        {
373	          g_day_g[p][d] = 0;
374	          g_day_m[p][d] = 0;
375	        }
376	    }
377	}
