379	/* Reconcile the window with the wall clock.  Safe on every path that
380	 * touches the history -- it is a no-op within a single day.
381	 */
382	static void vp_sync_day(void)
383	{
384	  long today = vp_today_num();
385	
386	  if (today < 0)
387	    {
388	      return;              /* clock unusable -- leave the window alone */
389	    }
390	
391	  if (g_hist_day < 0)
392	    {
393	      /* First run, or a VP01 file: the data in the window is real, we just
394	       * never knew which day it belonged to.  Adopt today, do not shift.
395	       */
396	      g_hist_day = today;
397	      vp_history_save();
398	      return;
399	    }
400	
401	  if (today <= g_hist_day)
402	    {
403	      /* Same day, or the clock jumped backwards -- which the build-date
404	       * boot anchor does on every cold start.  Never shift backwards: it
405	       * would drop real days off the front and zero slots that hold data.
406	       */
407	      return;
408	    }
409	
410	  vp_shift_days((int)(today - g_hist_day));
411	  g_hist_day = today;
412	  vp_history_save();
413	}
