22	#define TODAY (DAYS - 1)
23	
24	static int g_day_g[VELAPAW_MAX_PETS][DAYS];      /* grams per day */
25	static int g_day_m[VELAPAW_MAX_PETS][DAYS];      /* meals per day */
26	static int g_bcs[VELAPAW_MAX_PETS];              /* last BCS: 0/1/2, -1 none */
27	
28	/* Civil day number (see vp_days_from_civil) that owns slot TODAY, or -1
29	 * when it is not known yet: an unset clock, or a pre-VP02 history file.
30	 */
31	static long g_hist_day = -1;
32	
33	static int valid(velapaw_pet_id_t id)
34	{
35	  return id >= 0 && id < VELAPAW_MAX_PETS;
36	}
