38	/****************************************************************************
39	 * Agent-readable persistence
40	 *
41	 * The on-device ai_agent needs real feeding data to summarise, and its
42	 * read_file tool is sandboxed to the agent data dir, so everything lands
43	 * under <agent data dir>/velapaw/:
44	 *
45	 *   history.bin  compact machine copy of the rolling window, reloaded at
46	 *                init so the history survives a reboot
47	 *   status.md    the digest a skill reads: per-pet totals, baseline,
48	 *                appetite %, body condition, drop alert
49	 *   feed_log.md  append-only recent events, size-capped
50	 *
51	 * Doing this from the velapaw task directly is safe: since the ai_agent
52	 * merge every task stack is carved from the XTENSA_IMEM heap and lives in
53	 * internal SRAM (measured: velapaw StackBase 0x3fcabc98), so a littlefs
54	 * write no longer runs with the stack sitting behind the disabled flash
55	 * cache -- the freeze that identity.c's worker thread exists to dodge.
56	 * If a stack ever moves back to PSRAM (0x3c......), these calls must move
57	 * onto that worker-thread pattern too.
58	 *
59	 * Every write is best-effort.  If /data is not mounted the calls fail
60	 * quietly and the in-memory analytics behave exactly as they did before.
61	 ****************************************************************************/
62	
63	#ifdef CONFIG_EXAMPLES_AI_AGENT_VELA_DATA_DIR
64	#  define VP_AGENT_DIR CONFIG_EXAMPLES_AI_AGENT_VELA_DATA_DIR
65	#else
66	#  define VP_AGENT_DIR "/data/ai_agent"
67	#endif
68	
69	#define VP_DIR      VP_AGENT_DIR "/velapaw"
70	#define VP_HISTORY  VP_DIR "/history.bin"
71	#define VP_STATUS   VP_DIR "/status.md"
72	#define VP_FEEDLOG  VP_DIR "/feed_log.md"
73	
74	/* read_file tops out at 32 KB and the /data partition is under 1 MB. */
75	#define VP_LOG_MAX  8192
76	#define VP_MAGIC_V1 0x56503031u        /* "VP01" -- before the day stamp */
77	#define VP_MAGIC    0x56503032u        /* "VP02" */
78	
79	/* Below this the realtime clock is clearly unset; printing a 1970 date
80	 * would mislead the model, so the raw epoch is logged instead. */
81	#define VP_TS_SANE  1600000000
82	
83	static bool g_fs_ready;
