85	static bool vp_ensure_dir(void)
86	{
87	  if (g_fs_ready)
88	    {
89	      return true;
90	    }
91	
92	  if (mkdir(VP_AGENT_DIR, 0755) != 0 && errno != EEXIST)
93	    {
94	      return false;
95	    }
96	
97	  if (mkdir(VP_DIR, 0755) != 0 && errno != EEXIST)
98	    {
99	      return false;
100	    }
101	
102	  g_fs_ready = true;
103	  return true;
104	}
