106	static void vp_history_save(void)
107	{
108	  if (!vp_ensure_dir())
109	    {
110	      return;
111	    }
112	
113	  FILE *f = fopen(VP_HISTORY, "wb");
114	  if (f == NULL)
115	    {
116	      return;
117	    }
118	
119	  /* hdr[3] is the civil day owning slot TODAY, -1 when unknown. */
120	  uint32_t hdr[4] =
121	    {
122	      VP_MAGIC, VELAPAW_MAX_PETS, DAYS, (uint32_t)(int32_t)g_hist_day
123	    };
124	
125	  if (fwrite(hdr, sizeof(hdr), 1, f) == 1)
126	    {
127	      fwrite(g_day_g, sizeof(g_day_g), 1, f);
128	      fwrite(g_day_m, sizeof(g_day_m), 1, f);
129	      fwrite(g_bcs,   sizeof(g_bcs),   1, f);
130	    }
131	
132	  fclose(f);
133	}
