135	static void vp_history_load(void)
136	{
137	  FILE *f = fopen(VP_HISTORY, "rb");
138	  if (f == NULL)
139	    {
140	      return;
141	    }
142	
143	  uint32_t hdr[4];
144	  bool ok;
145	
146	  /* Geometry is part of the format: a rebuild that changes MAX_PETS or the
147	   * window length invalidates the file instead of misreading it. */
148	  ok = fread(hdr, sizeof(uint32_t), 3, f) == 3
149	       && hdr[1] == VELAPAW_MAX_PETS
150	       && hdr[2] == DAYS;
151	
152	  if (ok && hdr[0] == VP_MAGIC)
153	    {
154	      ok = fread(&hdr[3], sizeof(uint32_t), 1, f) == 1;
155	      g_hist_day = ok ? (long)(int32_t)hdr[3] : -1;
156	    }
157	  else if (ok && hdr[0] == VP_MAGIC_V1)
158	    {
159	      /* Pre-day-stamp file: the arrays are still good, the day simply was
160	       * never recorded.  vp_sync_day() adopts today without shifting,
161	       * rather than guessing and throwing real days away. */
162	      g_hist_day = -1;
163	    }
164	  else
165	    {
166	      ok = false;
167	    }
168	
169	  if (ok)
170	    {
171	      if (fread(g_day_g, sizeof(g_day_g), 1, f) != 1
172	          || fread(g_day_m, sizeof(g_day_m), 1, f) != 1
173	          || fread(g_bcs, sizeof(g_bcs), 1, f) != 1)
174	        {
175	          /* Short or corrupt: a clean slate beats a half-loaded history. */
176	          memset(g_day_g, 0, sizeof(g_day_g));
177	          memset(g_day_m, 0, sizeof(g_day_m));
178	          for (int i = 0; i < VELAPAW_MAX_PETS; i++)
179	            {
180	              g_bcs[i] = -1;
181	            }
182	
183	          printf("velapaw/store: %s corrupt, history reset\n", VP_HISTORY);
184	        }
185	      else
186	        {
187	          printf("velapaw/store: history restored from %s\n", VP_HISTORY);
188	        }
189	    }
190	
191	  fclose(f);
192	}
