332	/****************************************************************************
333	 * Day stamping
334	 *
335	 * The window is an array whose last slot is "today", so something has to
336	 * move it.  Until now the only thing that did was the EV_NEXTDAY demo
337	 * button, which means a board left running past midnight kept adding to the
338	 * same slot for ever.  Over-reporting intake makes the feeder withhold real
339	 * meals, so this is the dangerous direction to get wrong.
340	 ****************************************************************************/
341	
342	static long vp_days_from_civil(int y, unsigned m, unsigned d)
343	{
344	  /* Exact day number across month and year boundaries.  tm_yday alone is
345	   * not enough: 12-31 -> 01-01 has to be a delta of 1, not -364.
346	   */
347	  y -= m <= 2;
348	  long era = (y >= 0 ? y : y - 399) / 400;
349	  unsigned yoe = (unsigned)(y - era * 400);
350	  unsigned doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
351	  unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
352	  return era * 146097 + (long)doe - 719468;
353	}
354	
355	static long vp_today_num(void)
356	{
357	  time_t now = time(NULL);
358	  struct tm tmv;
359	
360	  /* Same sanity floor the feed log uses: an unset clock must never be
361	   * allowed to shift real history.
362	   */
363	  if (now < VP_TS_SANE)
364	    {
365	      return -1;
366	    }
367	
368	  localtime_r(&now, &tmv);
369	  return vp_days_from_civil(tmv.tm_year + 1900, tmv.tm_mon + 1, tmv.tm_mday);
370	}
371	
372	static void vp_shift_days(int n)
373	{
374	  if (n <= 0)
375	    {
376	      return;
377	    }
378	
379	  if (n > DAYS)
380	    {
381	      n = DAYS;
382	    }
383	
384	  for (int p = 0; p < VELAPAW_MAX_PETS; p++)
385	    {
386	      int d = 0;
387	      for (; d < DAYS - n; d++)
388	        {
389	          g_day_g[p][d] = g_day_g[p][d + n];
390	          g_day_m[p][d] = g_day_m[p][d + n];
391	        }
392	
393	      for (; d < DAYS; d++)
394	        {
395	          g_day_g[p][d] = 0;
396	          g_day_m[p][d] = 0;
397	        }
398	    }
399	}
