401	/* Reconcile the window with the wall clock.  Safe on every path that
402	 * touches the history -- it is a no-op within a single day.
403	 */
404	static void vp_sync_day(void)
405	{
406	  long today = vp_today_num();
407	
408	  if (today < 0)
409	    {
410	      return;              /* clock unusable -- leave the window alone */
411	    }
412	
413	  if (g_hist_day < 0)
414	    {
415	      /* First run, or a VP01 file: the data in the window is real, we just
416	       * never knew which day it belonged to.  Adopt today, do not shift.
417	       */
418	      g_hist_day = today;
419	      vp_history_save();
420	      return;
421	    }
422	
423	  if (today <= g_hist_day)
424	    {
425	      /* Same day, or the clock jumped backwards -- which the build-date
426	       * boot anchor does on every cold start.  Never shift backwards: it
427	       * would drop real days off the front and zero slots that hold data.
428	       */
429	      return;
430	    }
431	
432	  vp_shift_days((int)(today - g_hist_day));
433	  g_hist_day = today;
434	  vp_history_save();
435	}
