437	int velapaw_store_init(void)
438	{
439	  memset(g_day_g, 0, sizeof(g_day_g));
440	  memset(g_day_m, 0, sizeof(g_day_m));
441	  for (int i = 0; i < VELAPAW_MAX_PETS; i++)
442	    {
443	      g_bcs[i] = -1;
444	    }
445	
446	  vp_history_load();
447	
448	  /* A board that has been off -- or simply running -- across midnight has
449	   * to shift before it reports anything.
450	   */
451	  vp_sync_day();
452	
453	  /* Write the digest at startup too.  Without this, status.md does not exist
454	   * until the next feed, enroll or BCS update, so a freshly booted board
455	   * gives the agent's skill nothing to read. */
456	  vp_status_write();
457	  return 0;
458	}
