460	int velapaw_store_log_feeding(const struct velapaw_feed_event *ev)
461	{
462	  if (ev == NULL || !valid(ev->pet_id))
463	    {
464	      return -1;
465	    }
466	
467	  /* Bucket the event in the right day even if the board has been up since
468	   * before midnight.
469	   */
470	  vp_sync_day();
471	
472	  g_day_g[ev->pet_id][TODAY] += ev->grams;
473	  g_day_m[ev->pet_id][TODAY] += 1;
474	
475	  printf("    [store] event pet=%d grams=%d score=%.2f model=%s\n",
476	         ev->pet_id, ev->grams, ev->score, ev->model ? ev->model : "?");
477	
478	  vp_feedlog_append(ev);
479	  vp_persist();
480	  return 0;
