555	/* Alert on the most recent *completed* day (yesterday = TODAY-1) vs the
556	 * baseline of the days before it: a >50% drop is the early illness sign.
557	 */
558	int velapaw_store_alert_drop(velapaw_pet_id_t id)
559	{
560	  if (!valid(id) || DAYS < 3)
561	    {
562	      return 0;
563	    }
564	  int last = g_day_g[id][TODAY - 1];
565	  int sum = 0;
