574	void velapaw_store_seed(velapaw_pet_id_t id, int daily_g)
575	{
576	  if (!valid(id) || daily_g <= 0)
577	    {
578	      return;
579	    }
580	  /* fill the prior days with a normal baseline (deterministic +/- noise);
581	   * leave today (TODAY) at 0 so live feeding fills it in.
582	   */
583	  for (int d = 0; d < TODAY; d++)
584	    {
585	      int noise = ((id * 3 + d * 5) % 21) - 10;   /* -10..+10 g */
586	      int g = daily_g + noise;
587	      g_day_g[id][d] = g > 0 ? g : 0;
588	      g_day_m[id][d] = 2 + ((id + d) % 3);          /* 2..4 meals */
589	    }
590	
591	  /* Seeding happens at enrollment, which is the first moment a pet exists
592	   * to write a digest about. */
593	  vp_persist();
594	}
