1486	/* Delete a pet, keeping every per-pet table in step.
1487	 *
1488	 * Pet ids ARE array indices, so velapaw_identity_delete() renumbers every pet
1489	 * after the deleted one. Anything keyed by id must shift the same way or the
1490	 * data ends up on the wrong animal: the feeding history (store), the meal
1491	 * timeline tables here, and any id we're currently holding. */
1492	static void do_delete_pet(velapaw_pet_id_t id)
1493	{
1494	  int n = velapaw_identity_count();
1495	  int p, k;
1496	
1497	  if (id < 0 || id >= n)
1498	    {
1499	      return;
1500	    }
1501	
1502	  /* shift this file's per-pet tables down over the deleted slot */
1503	  for (p = id; p < VELAPAW_MAX_PETS - 1; p++)
1504	    {
1505	      for (k = 0; k < VELAPAW_MAX_MEALS; k++)
1506	        {
1507	          g_meal_fed_day[p][k] = g_meal_fed_day[p + 1][k];
1508	          g_meal_fed_min[p][k] = g_meal_fed_min[p + 1][k];
1509	          g_meal_fed_g[p][k]   = g_meal_fed_g[p + 1][k];
1510	          g_meal_skipped[p][k] = g_meal_skipped[p + 1][k];
1511	        }
1512	      g_last_fed[p] = g_last_fed[p + 1];
1513	    }
1514	  for (k = 0; k < VELAPAW_MAX_MEALS; k++)
1515	    {
1516	      g_meal_fed_day[VELAPAW_MAX_PETS - 1][k] = 0;   /* 0 = never fed */
1517	      g_meal_fed_min[VELAPAW_MAX_PETS - 1][k] = 0;
1518	      g_meal_fed_g[VELAPAW_MAX_PETS - 1][k]   = 0;
1519	      g_meal_skipped[VELAPAW_MAX_PETS - 1][k] = 0;
1520	    }
1521	  g_last_fed[VELAPAW_MAX_PETS - 1] = 0;
1522	
1523	  velapaw_store_delete(id);            /* history + BCS, shifted to match */
1524	  velapaw_identity_delete(id);         /* the pet itself + icon, renumbers rest */
1525	  velapaw_identity_save();             /* persist: stays deleted after reset */
1526	  velapaw_identity_save_icons();       /* icons were shifted too */
1527	
1528	  /* every id we were holding may now point at a different pet */
1529	  g_fed_visit = VELAPAW_PET_UNKNOWN;
1530	  g_bcs_for   = VELAPAW_PET_UNKNOWN;
1531	  g_cand      = VELAPAW_PET_UNKNOWN;
1532	  g_stable    = 0;
1533	
1534	  n = velapaw_identity_count();
1535	  if (g_trend_pet >= n) g_trend_pet = (n > 0) ? n - 1 : 0;
1536	  g_petn = n;
1537	
1538	  printf("velapaw/ui: deleted pet %d (%d left)\n", (int)id, n);
1539	}

