21	static bool meal_is_off(const char *s)
22	{
23	  return s != NULL && (strcmp(s, "off")     == 0 ||
24	                       strcmp(s, "OFF")     == 0 ||
25	                       strcmp(s, "Off")     == 0 ||
26	                       strcmp(s, "none")    == 0 ||
