2861	        {
2862	          /* Continue processing data from the EP0 OUT request queue */
2863	
2864	          esp32s3_epin_request(priv, privep);
2865	
2866	          /* If we are not actively processing an OUT request, then we need
2867	           * to setup to receive the next control request.
2868	           */
2869	
2870	          if (!privep->active)
2871	            {
2872	              esp32s3_ep0out_ctrlsetup(priv);
2873	              priv->ep0state = EP0STATE_IDLE;
2874	            }
2875	        }
