1889	static void esp32s3_req_complete(struct esp32s3_ep_s *privep,
1890	                                 int16_t result)
1891	{
1892	  struct esp32s3_req_s *privreq;
1893	
1894	  /* Remove the request at the head of the request list */
1895	
1896	  privreq = esp32s3_req_remfirst(privep);
1897	  DEBUGASSERT(privreq != NULL);
1898	
1899	  /* If endpoint 0, temporarily reflect the state of protocol stalled in the
1900	   * callback.
1901	   */
1902	
1903	  bool stalled = privep->stalled;
1904	  if (privep->epphy == EP0)
1905	    {
1906	      privep->stalled = privep->dev->stalled;
1907	    }
1908	
1909	  /* Save the result in the request structure */
1910	
1911	  privreq->req.result = result;
1912	
1913	  /* Callback to the request completion handler */
1914	
1915	  privreq->req.callback(&privep->ep, &privreq->req);
1916	
1917	  /* Restore the stalled indication */
1918	
1919	  privep->stalled = stalled;
1920	}
