1923	 * Name: esp32s3_req_cancel
1924	 *
1925	 * Description:
1926	 *   Cancel all pending requests for an endpoint
1927	 *
1928	 ****************************************************************************/
1929	
1930	static void esp32s3_req_cancel(struct esp32s3_ep_s *privep, int16_t status)
1931	{
1932	  if (!esp32s3_rqempty(privep))
1933	    {
1934	      esp32s3_ep_flush(privep);
1935	    }
1936	
1937	  while (!esp32s3_rqempty(privep))
1938	    {
1939	      usbtrace(TRACE_COMPLETE(privep->epphy),
1940	               (esp32s3_rqpeek(privep))->req.xfrd);
1941	      esp32s3_req_complete(privep, status);
1942	    }
1943	}
