972	static int cdcncm_packet_handler(FAR struct cdcncm_driver_s *self,
973	                                 FAR uint8_t *dgram, uint32_t dglen)
974	{
975	  FAR netpkt_t *pkt = netpkt_alloc(&self->dev, NETPKT_RX);
976	  int ret = -ENOMEM;
977	
978	  if (pkt == NULL)
979	    {
980	      return ret;
981	    }
