983	  ret = netpkt_copyin(&self->dev, pkt, dgram, dglen, 0);
984	  if (ret < 0)
985	    {
986	      netpkt_free(&self->dev, pkt, NETPKT_RX);
987	      return ret;
988	    }
989	
990	  ret = netpkt_tryadd_queue(pkt, &self->rx_queue);
991	  if (ret != 0)
992	    {
993	      netpkt_free(&self->dev, pkt, NETPKT_RX);
994	    }
995	
996	  return ret;
997	}
