2839	/****************************************************************************
2840	 * Name: esp32s3_epin
2841	 *
2842	 * Description:
2843	 *   This is part of the IN endpoint interrupt processing.  This function
2844	 *   handles the IN event for a single endpoint.
2845	 *
2846	 ****************************************************************************/
2847	
2848	static inline void esp32s3_epin(struct esp32s3_usbdev_s *priv, uint8_t epno)
2849	{
2850	  struct esp32s3_ep_s *privep = &priv->epin[epno];
2851	
2852	  /* Endpoint 0 is a special case. */
2853	
2854	  if (epno == 0)
2855	    {
2856	      /* In the EP0STATE_DATA_IN state, we are sending data from request
2857	       * buffer.  In that case, we must continue the request processing
2858	       */
2859	
2860	      if (priv->ep0state == EP0STATE_DATA_IN)
2861	        {
2862	          /* Continue processing data from the EP0 OUT request queue */
2863	
2864	          esp32s3_epin_request(priv, privep);
2865	
2866	          /* If we are not actively processing an OUT request, then we need
2867	           * to setup to receive the next control request.
2868	           */
2869	
2870	          if (!privep->active)
2871	            {
2872	              esp32s3_ep0out_ctrlsetup(priv);
2873	              priv->ep0state = EP0STATE_IDLE;
2874	            }
2875	        }
2876	
2877	      /* Test mode is another special case */
2878	
2879	      if (priv->dotest)
2880	        {
2881	          esp32s3_epin_runtestmode(priv);
2882	        }
2883	    }
2884	
2885	  /* For other endpoints, the only possibility is that we are continuing or
2886	   * finishing an IN request.
2887	   */
2888	
2889	  else if (priv->devstate == DEVSTATE_CONFIGURED)
2890	    {
2891	      /* Continue processing data from the endpoint write request queue */
2892	
2893	      esp32s3_epin_request(priv, privep);
2894	    }
2895	}
