2918	/****************************************************************************
2919	 * Name: esp32s3_epin_interrupt
2920	 *
2921	 * Description:
2922	 *   USB IN endpoint interrupt handler.  The core generates this interrupt
2923	 *   when an interrupt is pending on one of the IN endpoints of the core.
2924	 *   The driver must read the OTG DAINT register to determine the exact
2925	 *   number of the IN endpoint on which the interrupt occurred, and then
2926	 *   read the corresponding OTG DIEPINTx register to determine the exact
2927	 *   cause of the interrupt.
2928	 *
2929	 ****************************************************************************/
2930	
2931	static inline void esp32s3_epin_interrupt(struct esp32s3_usbdev_s *priv)
2932	{
2933	  uint32_t diepint;
2934	  uint32_t daint;
2935	  uint32_t mask;
2936	  uint32_t empty;
2937	  int epno;
2938	
2939	  /* Get the pending, enabled interrupts for the IN endpoint from the
2940	   * endpoint interrupt status register.
2941	   */
2942	
2943	  daint = esp32s3_getreg(ESP32S3_OTG_DAINT);
2944	  daint &= esp32s3_getreg(ESP32S3_OTG_DAINTMSK);
2945	  daint &= OTG_DAINT_IEP_MASK;
2946	
2947	  if (daint == 0)
2948	    {
2949	      /* We got an interrupt, but there is no unmasked endpoint that caused
2950	       * it?! When this happens, the interrupt flag never gets cleared and
2951	       * we are stuck in infinite interrupt loop.
2952	       *
2953	       * This shouldn't happen if we are diligent about handling timing
2954	       * issues when masking endpoint interrupts. However, this workaround
2955	       * avoids infinite loop and allows operation to continue normally.
2956	       * It works by clearing each endpoint flags, masked or not.
2957	       */
2958	
2959	      daint = esp32s3_getreg(ESP32S3_OTG_DAINT);
2960	      usbtrace(TRACE_DEVERROR(ESP32S3_TRACEERR_EPINUNEXPECTED),
2961	               (uint16_t)daint);
2962	
2963	      daint &= OTG_DAINT_IEP_MASK;
2964	      epno = 0;
2965	
2966	      while (daint)
2967	        {
2968	          if ((daint & 1) != 0)
2969	            {
2970	              uerr("DIEPINT(%d) = %08" PRIx32 "\n",
2971	                   epno, esp32s3_getreg(ESP32S3_OTG_DIEPINT(epno)));
2972	              esp32s3_putreg(0xff, ESP32S3_OTG_DIEPINT(epno));
2973	            }
2974	
2975	          epno++;
2976	          daint >>= 1;
2977	        }
2978	
2979	      return;
2980	    }
2981	
2982	  /* Process each pending IN endpoint interrupt */
2983	
2984	  epno = 0;
2985	  while (daint)
2986	    {
2987	      /* Is an IN interrupt pending for this endpoint? */
2988	
2989	      if ((daint & 1) != 0)
2990	        {
2991	          /* Get IN interrupt mask register.  Bits 0-6 correspond to enabled
2992	           * interrupts as will be found in the DIEPINT interrupt status
2993	           * register.
2994	           */
2995	
2996	          mask = esp32s3_getreg(ESP32S3_OTG_DIEPMSK);
2997	
2998	          /* Check if the TxFIFO not empty interrupt is enabled for this
2999	           * endpoint in the DIEPMSK register.  Bits n corresponds to
3000	           * endpoint n in the register. That condition corresponds to bit 7
3001	           * of the DIEPINT interrupt status register.  There is no TXFE bit
3002	           * in the mask register, so we fake one here.
3003	           */
3004	
3005	          empty = esp32s3_getreg(ESP32S3_OTG_DIEPEMPMSK);
3006	          if ((empty & OTG_DIEPEMPMSK(epno)) != 0)
3007	            {
3008	              mask |= OTG_DIEPINT_TXFE;
3009	            }
3010	
3011	          /* Now, read the interrupt status and mask out all disabled
3012	           * interrupts.
3013	           */
3014	
3015	          diepint = esp32s3_getreg(ESP32S3_OTG_DIEPINT(epno)) & mask;
3016	
3017	          /* Decode and process the enabled, pending interrupts */
3018	
3019	          /* Transfer completed interrupt */
3020	
3021	          if ((diepint & OTG_DIEPINT_XFRC) != 0)
3022	            {
3023	              usbtrace(TRACE_INTDECODE(ESP32S3_TRACEINTID_EPIN_XFRC),
3024	                       (uint16_t)diepint);
3025	
3026	              /* It is possible that logic may be waiting for a the TxFIFO to
3027	               * become empty.  We disable the TxFIFO empty interrupt here;
3028	               * it will be re-enabled if there is still insufficient space
3029	               * in the TxFIFO.
3030	               */
3031	
3032	              empty &= ~OTG_DIEPEMPMSK(epno);
3033	              esp32s3_putreg(empty, ESP32S3_OTG_DIEPEMPMSK);
3034	              esp32s3_putreg(OTG_DIEPINT_XFRC, ESP32S3_OTG_DIEPINT(epno));
3035	
3036	              /* IN transfer complete */
3037	
3038	              esp32s3_epin(priv, epno);
3039	            }
3040	
3041	          /* Timeout condition */
3042	
3043	          if ((diepint & OTG_DIEPINT_TOC) != 0)
3044	            {
3045	              usbtrace(TRACE_INTDECODE(ESP32S3_TRACEINTID_EPIN_TOC),
3046	                       (uint16_t)diepint);
3047	              esp32s3_putreg(OTG_DIEPINT_TOC, ESP32S3_OTG_DIEPINT(epno));
3048	            }
3049	
3050	          /* IN token received when TxFIFO is empty.  Applies to non-periodic
3051	           * IN endpoints only.  This interrupt indicates that an IN token
3052	           * was received when the associated TxFIFO (periodic/non-periodic)
3053	           * was empty. This interrupt is asserted on the endpoint for which
3054	           * the IN token was received.
3055	           */
3056	
3057	          if ((diepint & OTG_DIEPINT_ITTXFE) != 0)
3058	            {
3059	              usbtrace(TRACE_INTDECODE(ESP32S3_TRACEINTID_EPIN_ITTXFE),
