288	void nsh_dumpbuffer(FAR struct nsh_vtbl_s *vtbl, FAR const char *msg,
289	                    FAR const uint8_t *buffer, ssize_t nbytes)
290	{
291	  char line[128];
292	  size_t size;
293	  int ch;
294	  int i;
295	  int j;
296	
297	  nsh_output(vtbl, "%s:\n", msg);
298	  for (i = 0; i < nbytes; i += 16)
299	    {
300	      snprintf(line, sizeof(line), "%04x: ", i);
301	      size = strlen(line);
302	
303	      for (j = 0; j < 16; j++)
304	        {
305	          if (i + j < nbytes)
306	            {
307	              snprintf(&line[size], sizeof(line) - size,
308	                       "%02x ", buffer[i + j]);
309	            }
310	          else
311	            {
312	              strlcpy(&line[size], "   ", sizeof(line) - size);
313	            }
314	
315	          size += strlen(&line[size]);
316	        }
317	
318	      for (j = 0; j < 16; j++)
319	        {
320	          if (i + j < nbytes)
321	            {
322	              ch = buffer[i + j];
323	              snprintf(&line[size], sizeof(line) - size,
324	                       "%c", ch >= 0x20 && ch <= 0x7e ? ch : '.');
325	              size += strlen(&line[size]);
326	            }
327	        }
328	
329	      nsh_output(vtbl, "%s\n", line);
330	    }
331	}
