912	
913	static void cdcncm_transmit_work(FAR void *arg)
914	{
915	  FAR struct cdcncm_driver_s *self = arg;
916	  FAR const struct ndp_parser_opts_s *opts = self->parseropts;
917	  FAR uint8_t *tmp;
918	  const int dgramidxlen = 2 * opts->dgramitemlen;
919	  const int ndpalign = g_ntbparameters.ndpinalignment;
920	  int ncblen;
921	  int ndpindex;
922	  int totallen;
923	
924	  /* Wait until the USB device request for Ethernet frame transmissions
925	   * becomes available.
926	   */
927	
928	  while (nxsem_wait(&self->wrreq_idle) != OK)
929	    {
930	    }
931	
932	  ncblen   = opts->nthsize;
933	  ndpindex = NCM_ALIGN(ncblen, ndpalign);
934	
935	  /* Fill NCB */
936	
937	  tmp      = self->wrreq->buf + 8; /* Offset to block length */
938	  totallen = self->dgramaddr - self->wrreq->buf;
939	  cdcncm_put(&tmp, opts->blocklen, totallen);
940	
941	  /* Fill NDP */
942	
943	  tmp = self->wrreq->buf + ndpindex + 4; /* Offset to ndp length */
944	  cdcncm_put(&tmp, 2, opts->ndpsize + (self->dgramcount + 1) * dgramidxlen);
945	
946	  tmp += opts->reserved1 + opts->nextndpindex + opts->reserved2 +
947	         self->dgramcount * dgramidxlen;
948	  self->dgramcount = 0;
949	
950	  cdcncm_put(&tmp, opts->dgramitemlen, 0);
951	  cdcncm_put(&tmp, opts->dgramitemlen, 0);
952	
953	  self->wrreq->len = totallen;
954	
955	  EP_SUBMIT(self->epbulkin, self->wrreq);
956	}
