958	/****************************************************************************
959	 * Name: cdcncm_packet_handler
960	 *
961	 * Description:
962	 *   Sends a single complete packet to the protocol stack
963	 *
964	 * Input Parameters:
965	 *   self - Reference to the driver state structure
966	 *
967	 * Returned Value:
968	 *   None
969	 *
970	 ****************************************************************************/
971	
972	static int cdcncm_packet_handler(FAR struct cdcncm_driver_s *self,
973	                                 FAR uint8_t *dgram, uint32_t dglen)
974	{
975	  FAR netpkt_t *pkt = netpkt_alloc(&self->dev, NETPKT_RX);
976	  int ret = -ENOMEM;
977	
978	  if (pkt == NULL)
979	    {
980	      return ret;
981	    }
982	
983	  ret = netpkt_copyin(&self->dev, pkt, dgram, dglen, 0);
984	  if (ret < 0)
985	    {
986	      netpkt_free(&self->dev, pkt, NETPKT_RX);
987	      return ret;
988	    }
989	
990	  ret = netpkt_tryadd_queue(pkt, &self->rx_queue);
991	  if (ret != 0)
992	    {
993	      netpkt_free(&self->dev, pkt, NETPKT_RX);
994	    }
995	
996	  return ret;
997	}
