999	/****************************************************************************
1000	 * Name: cdcncm_receive
1001	 *
1002	 * Description:
1003	 *   An interrupt was received indicating the availability of a new RX packet
1004	 *
1005	 * Input Parameters:
1006	 *   self - Reference to the driver state structure
1007	 *
1008	 * Returned Value:
1009	 *   None
1010	 *
1011	 ****************************************************************************/
1012	
1013	static void cdcncm_receive(FAR struct cdcncm_driver_s *self)
1014	{
1015	  FAR const struct ndp_parser_opts_s *opts = self->parseropts;
1016	  FAR uint8_t *tmp = self->rdreq->buf;
1017	  uint32_t ntbmax = g_ntbparameters.ntboutmaxsize;
1018	  uint32_t blocklen;
1019	  uint32_t ndplen;

1019	  uint32_t ndplen;
1020	  int ndpindex;
1021	  int dgramcounter;
1022	
1023	  /* Get signature */
1024	
1025	  if (GETUINT32(tmp) != opts->nthsign)
1026	    {
1027	      uerr("Wrong NTH SIGN, skblen %zu\n", self->rdreq->xfrd);
1028	      return;
1029	    }
1030	
1031	  tmp += 4;
1032	
1033	  /* Get header len */
1034	
1035	  if (GETUINT16(tmp) != opts->nthsize)
1036	    {
1037	      uerr("Wrong NTB headersize\n");
1038	      return;
1039	    }
1040	
1041	  tmp += 4; /* Skip header len and seq */
1042	
1043	  blocklen = cdcncm_get(&tmp, opts->blocklen);
1044	
1045	  /* Get block len */
1046	
1047	  if (blocklen > ntbmax)
1048	    {
1049	      uerr("OUT size exceeded\n");
1050	      return;
1051	    }
1052	
1053	  ndpindex = cdcncm_get(&tmp, opts->ndpindex);
1054	
1055	  do
1056	    {
1057	      uint32_t index;
1058	      uint32_t dglen;
1059	
1060	      if (((ndpindex % 4) != 0) || (ndpindex < opts->nthsize) ||
1061	          (ndpindex > (blocklen - opts->ndpsize)))
1062	        {
1063	          uerr("Bad index: %#X\n", ndpindex);
1064	          return;
1065	        }
1066	
1067	      tmp = self->rdreq->buf + ndpindex;
1068	
1069	      if (GETUINT32(tmp) != self->ndpsign)
1070	        {
1071	          uerr("Wrong NDP SIGN\n");
1072	          return;
1073	        }
1074	
1075	      tmp   += 4;
1076	      ndplen = cdcncm_get(&tmp, 2);
1077	
1078	      if ((ndplen < opts->ndpsize + 2 * (opts->dgramitemlen * 2)) ||
1079	          (ndplen % opts->ndpalign != 0))
1080	        {
1081	          uerr("Bad NDP length: %04" PRIx32 " \n", ndplen);
1082	          return;
1083	        }
1084	
1085	      tmp         += opts->reserved1;
1086	      ndpindex     = cdcncm_get(&tmp, opts->nextndpindex);
1087	      tmp         += opts->reserved2;
1088	
1089	      ndplen      -= opts->ndpsize;
1090	      dgramcounter = 0;
1091	      do
1092	        {
1093	          index = cdcncm_get(&tmp, opts->dgramitemlen);
1094	          dglen = cdcncm_get(&tmp, opts->dgramitemlen);
1095	
1096	          /* TODO: support CRC */
1097	
1098	          /* Check if the packet is a valid size for the network buffer
1099	           * configuration.
1100	           */
1101	
1102	          if (index == 0 || dglen == 0)
1103	            {
1104	              break;
1105	            }
1106	
1107	          dgramcounter++;
1108	
1109	          /* Copy the data from the hardware to self->rx_queue. */
1110	
1111	          cdcncm_packet_handler(self, self->rdreq->buf + index, dglen);
1112	
1113	          ndplen -= 2 * (opts->dgramitemlen);
1114	        }
1115	      while (ndplen > 2 * (opts->dgramitemlen));
1116	    }
1117	  while (ndpindex);
1118	}
