1141	/****************************************************************************
1142	 * Name: cdcncm_interrupt_work
1143	 *
1144	 * Description:
1145	 *   Perform interrupt related work from the worker thread
1146	 *
1147	 * Input Parameters:
1148	 *   arg - The argument passed when work_queue() was called.
1149	 *
1150	 * Returned Value:
1151	 *   OK on success
1152	 *
1153	 * Assumptions:
1154	 *   Runs on a worker thread.
1155	 *
1156	 ****************************************************************************/
1157	
1158	static void cdcncm_interrupt_work(FAR void *arg)
1159	{
1160	  FAR struct cdcncm_driver_s *self = (FAR struct cdcncm_driver_s *)arg;
1161	
1162	  /* Check if we received an incoming packet, if so, call cdcncm_receive() */
1163	
1164	  if (self->rxpending)
1165	    {
1166	      cdcncm_receive(self);
1167	      netdev_lower_rxready(&self->dev);
1168	
1169	      self->rxpending = false;
1170	      EP_SUBMIT(self->epbulkout, self->rdreq);
1171	    }
1172	
1173	  /* Check if a packet transmission just completed.  If so, call
1174	   * cdcncm_txdone. This may disable further Tx interrupts if there
1175	   * are no pending transmissions.
1176	   */
1177	
1178	  if (self->txdone)
1179	    {
1180	      self->txdone = false;
1181	
1182	      cdcncm_txdone(self);
1183	    }
1184	}
