1468	
1469	  switch (req->result)
1470	    {
1471	      case 0:  /* Normal completion */
1472	        {
1473	          DEBUGASSERT(!self->rxpending);
1474	          self->rxpending = true;
1475	          work_queue(ETHWORK, &self->irqwork,
1476	                     cdcncm_interrupt_work, self, 0);
1477	        }
1478	        break;
1479	
1480	      case -ESHUTDOWN:  /* Disconnection */
1481	        break;
1482	
1483	      default: /* Some other error occurred */
1484	        {
1485	          uerr("req->result: %hd\n", req->result);
1486	          EP_SUBMIT(self->epbulkout, self->rdreq);
1487	        }
1488	        break;
