4462	/****************************************************************************
4463	 * Name: esp32s3_ep_submit
4464	 *
4465	 * Description:
4466	 *   Submit an I/O request to the endpoint
4467	 *
4468	 ****************************************************************************/
4469	
4470	static int esp32s3_ep_submit(struct usbdev_ep_s *ep,
4471	                             struct usbdev_req_s *req)
4472	{
4473	  struct esp32s3_req_s *privreq = (struct esp32s3_req_s *)req;
4474	  struct esp32s3_ep_s *privep = (struct esp32s3_ep_s *)ep;
4475	  struct esp32s3_usbdev_s *priv;
4476	  irqstate_t flags;
4477	  int ret = OK;
4478	
4479	  /* Some sanity checking */
4480	
4481	#ifdef CONFIG_DEBUG_FEATURES
4482	  if (!req || !req->callback || !req->buf || !ep)
4483	    {
4484	      usbtrace(TRACE_DEVERROR(ESP32S3_TRACEERR_INVALIDPARMS), 0);
4485	      uinfo("req=%p callback=%p buf=%p ep=%p\n",
4486	            req, req->callback, req->buf, ep);
4487	      return -EINVAL;
4488	    }
4489	#endif
4490	
4491	  usbtrace(TRACE_EPSUBMIT, privep->epphy);
4492	  priv = privep->dev;
4493	
4494	#ifdef CONFIG_DEBUG_FEATURES
4495	  if (!priv->driver)
4496	    {
4497	      usbtrace(TRACE_DEVERROR(ESP32S3_TRACEERR_NOTCONFIGURED),
4498	               priv->usbdev.speed);
4499	      return -ESHUTDOWN;
4500	    }
4501	#endif
4502	
4503	  /* Handle the request from the class driver */
4504	
4505	  req->result = -EINPROGRESS;
4506	  req->xfrd = 0;
4507	
4508	  /* Disable Interrupts */
4509	
4510	  flags = enter_critical_section();
4511	
4512	  /* If we are stalled, then drop all requests on the floor */
4513	
4514	  if (privep->stalled)
4515	    {
4516	      ret = -EBUSY;
4517	    }
4518	  else
4519	    {
4520	      /* Add the new request to the request queue for the endpoint. */
4521	
4522	      if (esp32s3_req_addlast(privep, privreq) && !privep->active)
4523	        {
4524	          /* If a request was added to an IN endpoint, then attempt to send
4525	           * the request data buffer now.
4526	           */
4527	
4528	          if (privep->isin)
4529	            {
4530	              usbtrace(TRACE_INREQQUEUED(privep->epphy), privreq->req.len);
4531	
4532	              /* If the endpoint is not busy with another write request, then
4533	               * process the newly received write request now.
4534	               */
4535	
4536	              if (!privep->active)
4537	                {
4538	                  esp32s3_epin_request(priv, privep);
4539	                }
4540	            }
4541	
4542	          /* If the request was added to an OUT endpoint, then attempt to
4543	           * setup a read into the request data buffer now (this will,
4544	           * of course, fail if there is already a read in place).
4545	           */
4546	
4547	          else
4548	            {
4549	              usbtrace(TRACE_OUTREQQUEUED(privep->epphy), privreq->req.len);
4550	              esp32s3_epout_request(priv, privep);
4551	            }
4552	        }
4553	    }
4554	
4555	  leave_critical_section(flags);
4556	  return ret;
4557	}
