4711	
4712	  /* Is this an IN endpoint? */
4713	
4714	  if (privep->isin == 1)
4715	    {
4716	      return esp32s3_epin_setstall(privep);
4717	    }
4718	  else
4719	    {
4720	      return esp32s3_epout_setstall(privep);
4721	    }
