4724	/****************************************************************************
4725	 * Name: esp32s3_ep_clrstall
4726	 *
4727	 * Description:
4728	 *   Resume a stalled endpoint
4729	 *
4730	 ****************************************************************************/
4731	
4732	static int esp32s3_ep_clrstall(struct esp32s3_ep_s *privep)
4733	{
4734	  uint32_t regaddr;
4735	  uint32_t regval;
4736	  uint32_t stallbit;
4737	  uint32_t data0bit;
4738	
4739	  usbtrace(TRACE_EPRESUME, privep->epphy);
4740	
4741	  /* Is this an IN endpoint? */
4742	
4743	  if (privep->isin == 1)
4744	    {
4745	      /* Clear the stall bit in the IN endpoint device control register */
4746	
4747	      regaddr = ESP32S3_OTG_DIEPCTL(privep->epphy);
4748	      stallbit = OTG_DIEPCTL_STALL;
4749	      data0bit = OTG_DIEPCTL_SD0PID;
4750	    }
4751	  else
4752	    {
4753	      /* Clear the stall bit in the IN endpoint device control register */
4754	
4755	      regaddr = ESP32S3_OTG_DOEPCTL(privep->epphy);
4756	      stallbit = OTG_DOEPCTL_STALL;
4757	      data0bit = OTG_DOEPCTL_SD0PID;
4758	    }
4759	
4760	  /* Clear the stall bit */
4761	
4762	  regval = esp32s3_getreg(regaddr);
4763	  regval &= ~stallbit;
4764	
4765	  /* Set the DATA0 pid for interrupt and bulk endpoints */
4766	
4767	  if (privep->eptype == USB_EP_ATTR_XFER_INT ||
4768	      privep->eptype == USB_EP_ATTR_XFER_BULK)
4769	    {
4770	      /* Writing this bit sets the DATA0 PID */
4771	
4772	      regval |= data0bit;
4773	    }
4774	
4775	  esp32s3_putreg(regval, regaddr);
4776	
4777	  /* The endpoint is no longer stalled */
4778	
4779	  privep->stalled = false;
4780	  return OK;
4781	}
