4783	/****************************************************************************
4784	 * Name: esp32s3_ep_stall
4785	 *
4786	 * Description:
4787	 *   Stall or resume an endpoint
4788	 *
4789	 ****************************************************************************/
4790	
4791	static int esp32s3_ep_stall(struct usbdev_ep_s *ep, bool resume)
4792	{
4793	  struct esp32s3_ep_s *privep = (struct esp32s3_ep_s *)ep;
4794	  irqstate_t flags;
4795	  int ret;
4796	
4797	  /* Set or clear the stall condition as requested */
4798	
4799	  flags = enter_critical_section();
4800	  if (resume)
4801	    {
4802	      ret = esp32s3_ep_clrstall(privep);
4803	    }
4804	  else
4805	    {
4806	      ret = esp32s3_ep_setstall(privep);
4807	    }
4808	
4809	  leave_critical_section(flags);
4810	
4811	  return ret;
4812	}
