2581	static void cdcncm_unbind(FAR struct usbdevclass_driver_s *driver,
2582	                          FAR struct usbdev_s *dev)
2583	{
2584	  FAR struct cdcncm_driver_s *self = (FAR struct cdcncm_driver_s *)driver;
2585	
2586	#ifdef CONFIG_DEBUG_FEATURES
2587	  if (!driver || !dev)
2588	    {
2589	      usbtrace(TRACE_CLSERROR(USBSER_TRACEERR_INVALIDARG), 0);
2590	      return;
2591	    }
2592	#endif
2593	
2594	  /* Make sure that the endpoints have been unconfigured.  If
2595	   * we were terminated gracefully, then the configuration should
2596	   * already have been reset.  If not, then calling cdcacm_resetconfig
2597	   * should cause the endpoints to immediately terminate all
2598	   * transfers and return the requests to us (with result == -ESHUTDOWN)
2599	   */
2600	
2601	  cdcncm_resetconfig(self);
2602	  up_mdelay(50);
2603	
2604	  /* Free the interrupt IN endpoint */
2605	
2606	  if (self->epint)
2607	    {
2608	      DEV_FREEEP(dev, self->epint);
2609	      self->epint = NULL;
2610	    }
2611	
2612	  /* Free the pre-allocated control request */
2613	
2614	  if (self->ctrlreq != NULL)
2615	    {
2616	      usbdev_freereq(dev->ep0, self->ctrlreq);
2617	      self->ctrlreq = NULL;
2618	    }
2619	
2620	  /* Free pre-allocated read requests (which should all have
2621	   * been returned to the free list at this time -- we don't check)
2622	   */
2623	
2624	  if (self->rdreq != NULL)
2625	    {
2626	      usbdev_freereq(self->epbulkout, self->rdreq);
2627	      self->rdreq = NULL;
2628	    }
2629	
2630	  /* Free the bulk OUT endpoint */
2631	
2632	  if (self->epbulkout)
2633	    {
2634	      DEV_FREEEP(dev, self->epbulkout);
2635	      self->epbulkout = NULL;
2636	    }
2637	
2638	  /* Free write requests that are not in use (which should be all
2639	   * of them)
2640	   */
2641	
2642	  if (self->wrreq != NULL)
2643	    {
2644	      usbdev_freereq(self->epbulkin, self->wrreq);
2645	      self->wrreq = NULL;
2646	    }
2647	
2648	  /* Free the bulk IN endpoint */
2649	
2650	  if (self->epbulkin)
2651	    {
2652	      DEV_FREEEP(dev, self->epbulkin);
2653	      self->epbulkin = NULL;
2654	    }
2655	
2656	  /* Clear out all data in the rx_queue */
2657	
2658	  netpkt_free_queue(&self->rx_queue);
2659	}
