2789	                  iob_free_chain(iob);
2790	                  uerr("CDCMBIM add rx queue failed: %d\n", ret);
2791	                  return ret;
2792	                }
2793	
2794	              nxsem_post(&mbim->read_sem);
2795	              poll_notify(mbim->fds, CDC_MBIM_NPOLLWAITERS, POLLIN);
2796	            }
2797	            break;
2798	
2799	          case MBIM_GET_RESPONSE:
