2899	#else
2900	  self->usbdev.speed = USB_SPEED_FULL;
2901	#endif
2902	  self->usbdev.ops   = &g_usbdevops;
2903	
2904	  memcpy(&self->devinfo, devinfo, sizeof(struct usbdev_devinfo_s));
2905	
2906	  /* Put the interface in the down state.  This usually amounts to resetting
2907	   * the device and/or calling cdcncm_ifdown().
2908	   */
