5422	
5423	#if ESP32S3_ENDPOINT_NUM > 0
5424	  address = ESP32S3_RXFIFO_WORDS;
5425	  regval = (address << OTG_DIEPTXF0_TX0FD_SHIFT) |
5426	    (ESP32S3_EP0_TXFIFO_WORDS << OTG_DIEPTXF0_TX0FSA_SHIFT);
5427	  esp32s3_putreg(regval, ESP32S3_OTG_DIEPTXF0);
5428	#endif
5429	
5430	#if ESP32S3_ENDPOINT_NUM > 1
5431	  address += ESP32S3_EP0_TXFIFO_WORDS;
5432	  regval = (address << OTG_DIEPTXF_INEPTXSA_SHIFT) |
5433	    (ESP32S3_EP1_TXFIFO_WORDS << OTG_DIEPTXF_INEPTXFD_SHIFT);
5434	  esp32s3_putreg(regval, ESP32S3_OTG_DIEPTXF(1));
5435	#endif
5436	
5437	#if ESP32S3_ENDPOINT_NUM > 2
5438	  address += ESP32S3_EP1_TXFIFO_WORDS;
5439	  regval = (address << OTG_DIEPTXF_INEPTXSA_SHIFT) |
5440	    (ESP32S3_EP2_TXFIFO_WORDS << OTG_DIEPTXF_INEPTXFD_SHIFT);
5441	  esp32s3_putreg(regval, ESP32S3_OTG_DIEPTXF(2));
5442	#endif
5443	
5444	#if ESP32S3_ENDPOINT_NUM > 3
5445	  address += ESP32S3_EP2_TXFIFO_WORDS;
5446	  regval = (address << OTG_DIEPTXF_INEPTXSA_SHIFT) |
5447	    (ESP32S3_EP3_TXFIFO_WORDS << OTG_DIEPTXF_INEPTXFD_SHIFT);
5448	  esp32s3_putreg(regval, ESP32S3_OTG_DIEPTXF(3));
