5450	
5451	#if ESP32S3_ENDPOINT_NUM > 4
5452	  address += ESP32S3_EP3_TXFIFO_WORDS;
5453	  regval = (address << OTG_DIEPTXF_INEPTXSA_SHIFT) |
5454	    (ESP32S3_EP4_TXFIFO_WORDS << OTG_DIEPTXF_INEPTXFD_SHIFT);
5455	  esp32s3_putreg(regval, ESP32S3_OTG_DIEPTXF(4));
5456	#endif
5457	
5458	#if ESP32S3_ENDPOINT_NUM > 5
5459	  address += ESP32S3_EP4_TXFIFO_WORDS;
5460	  regval = (address << OTG_DIEPTXF_INEPTXSA_SHIFT) |
5461	    (ESP32S3_EP5_TXFIFO_WORDS << OTG_DIEPTXF_INEPTXFD_SHIFT);
5462	  esp32s3_putreg(regval, ESP32S3_OTG_DIEPTXF(5));
5463	#endif
5464	
5465	#if ESP32S3_ENDPOINT_NUM > 6
5466	  address += ESP32S3_EP5_TXFIFO_WORDS;
5467	  regval = (address << OTG_DIEPTXF_INEPTXSA_SHIFT) |
5468	    (ESP32S3_EP6_TXFIFO_WORDS << OTG_DIEPTXF_INEPTXFD_SHIFT);
5469	  esp32s3_putreg(regval, ESP32S3_OTG_DIEPTXF(6));
5470	#endif
5471	
