1453	/****************************************************************************
1454	 * Name: cdcncm_rdcomplete
1455	 *
1456	 * Description:
1457	 *   Handle completion of read request on the bulk OUT endpoint.
1458	 *
1459	 ****************************************************************************/
1460	
1461	static void cdcncm_rdcomplete(FAR struct usbdev_ep_s *ep,
1462	                              FAR struct usbdev_req_s *req)
1463	{
1464	  FAR struct cdcncm_driver_s *self = (FAR struct cdcncm_driver_s *)ep->priv;
1465	
1466	  uinfo("buf: %p, flags 0x%hhx, len %zu, xfrd %zu, result %hd\n",
1467	        req->buf, req->flags, req->len, req->xfrd, req->result);
1468	
1469	  switch (req->result)
1470	    {
1471	      case 0:  /* Normal completion */
1472	        {
1473	          DEBUGASSERT(!self->rxpending);
1474	          self->rxpending = true;
1475	          work_queue(ETHWORK, &self->irqwork,
1476	                     cdcncm_interrupt_work, self, 0);
1477	        }
1478	        break;
1479	
1480	      case -ESHUTDOWN:  /* Disconnection */
1481	        break;
1482	
1483	      default: /* Some other error occurred */
1484	        {
1485	          uerr("req->result: %hd\n", req->result);
1486	          EP_SUBMIT(self->epbulkout, self->rdreq);
1487	        }
1488	        break;
1489	    }
1490	}
