1499	 ****************************************************************************/
1500	
1501	static void cdcncm_wrcomplete(FAR struct usbdev_ep_s *ep,
1502	                              FAR struct usbdev_req_s *req)
1503	{
1504	  FAR struct cdcncm_driver_s *self = (FAR struct cdcncm_driver_s *)ep->priv;
1505	  int rc;
1506	
1507	  uinfo("buf: %p, flags 0x%hhx, len %zu, xfrd %zu, result %hd\n",
1508	        req->buf, req->flags, req->len, req->xfrd, req->result);
1509	
1510	  /* The single USB device write request is available for upcoming
1511	   * transmissions again.
1512	   */
1513	
1514	  rc = nxsem_post(&self->wrreq_idle);
1515	
1516	  if (rc != OK)
1517	    {
1518	      nerr("nxsem_post failed! rc: %d\n", rc);
1519	    }
