1527	/****************************************************************************
1528	 * Name: cdcncm_resetconfig
1529	 *
1530	 * Description:
1531	 *   Mark the device as not configured and disable all endpoints.
1532	 *
1533	 ****************************************************************************/
1534	
1535	static void cdcncm_resetconfig(FAR struct cdcncm_driver_s *self)
1536	{
1537	  /* Are we configured? */
1538	
1539	  if (self->config != CDCECM_CONFIGID_NONE)
1540	    {
1541	      /* Yes.. but not anymore */
1542	
1543	      self->config = CDCECM_CONFIGID_NONE;
1544	
1545	      /* Inform the networking layer that the link is down */
1546	
1547	      cdcncm_ifdown(&self->dev);
1548	
1549	      /* Disable endpoints.  This should force completion of all pending
1550	       * transfers.
1551	       */
1552	
1553	      EP_DISABLE(self->epint);
1554	      EP_DISABLE(self->epbulkin);
1555	      EP_DISABLE(self->epbulkout);
1556	      self->notify = NCM_NOTIFY_SPEED;
1557	    }
1558	
1559	  self->parseropts = &g_ndp16_opts;
1560	  self->ndpsign    = self->isncm ? self->parseropts->ndpsign :
1561	                                   CDC_MBIM_NDP16_NOCRC_SIGN;
1562	}
