1564	/****************************************************************************
1565	 * Name: cdcncm_setconfig
1566	 *
1567	 *   Set the device configuration by allocating and configuring endpoints and
1568	 *   by allocating and queue read and write requests.
1569	 *
1570	 ****************************************************************************/
1571	
1572	static int cdcncm_setconfig(FAR struct cdcncm_driver_s *self, uint8_t config)
1573	{
1574	  struct usb_ss_epdesc_s epdesc;
1575	  int ret;
1576	
1577	  if (config == self->config)
1578	    {
1579	      return OK;
1580	    }
1581	
1582	  cdcncm_resetconfig(self);
1583	
1584	  if (config == CDCECM_CONFIGID_NONE)
1585	    {
1586	      return OK;
1587	    }
1588	
1589	  if (config != CDCECM_CONFIGID)
1590	    {
1591	      return -EINVAL;
1592	    }
1593	
1594	  cdcncm_mkepdesc(CDCNCM_EP_INTIN_IDX,
1595	                  &epdesc.epdesc, &self->devinfo, self->usbdev.speed);
1596	  ret = EP_CONFIGURE(self->epint, &epdesc.epdesc, false);
1597	
1598	  if (ret < 0)
1599	    {
1600	      goto error;
1601	    }
1602	
1603	  self->epint->priv = self;
1604	  cdcncm_mkepdesc(CDCNCM_EP_BULKIN_IDX,
1605	                  &epdesc.epdesc, &self->devinfo, self->usbdev.speed);
1606	  ret = EP_CONFIGURE(self->epbulkin, &epdesc.epdesc, false);
1607	
1608	  if (ret < 0)
1609	    {
1610	      goto error;
1611	    }
1612	
1613	  self->epbulkin->priv = self;
1614	
1615	  cdcncm_mkepdesc(CDCNCM_EP_BULKOUT_IDX,
1616	                  &epdesc.epdesc, &self->devinfo, self->usbdev.speed);
1617	  ret = EP_CONFIGURE(self->epbulkout, &epdesc.epdesc, true);
1618	
1619	  if (ret < 0)
1620	    {
1621	      goto error;
1622	    }
1623	
1624	  self->epbulkout->priv = self;
1625	
1626	  /* Queue read requests in the bulk OUT endpoint */
1627	
1628	  DEBUGASSERT(!self->rxpending);
1629	
1630	  self->rdreq->callback = cdcncm_rdcomplete,
1631	  ret = EP_SUBMIT(self->epbulkout, self->rdreq);
1632	  if (ret != OK)
1633	    {
1634	      uerr("EP_SUBMIT failed. ret %d\n", ret);
1635	      goto error;
1636	    }
1637	
1638	  /* We are successfully configured */
1639	
1640	  self->config = config;
1641	
1642	  /* Set client's MAC address */
1643	
1644	  memcpy(self->dev.netdev.d_mac.ether.ether_addr_octet,
1645	         "\x00\xe0\xde\xad\xbe\xef", IFHWADDRLEN);
1646	
1647	  /* Report link up to networking layer */
1648	
1649	  if (cdcncm_ifup(&self->dev) == OK)
1650	    {
1651	      self->dev.netdev.d_flags |= IFF_UP;
1652	    }
1653	
1654	  return OK;
1655	
1656	error:
1657	  cdcncm_resetconfig(self);
1658	  return ret;
1659	}
