2934	  uint32_t daint;
2935	  uint32_t mask;
2936	  uint32_t empty;
2937	  int epno;
2938	
2939	  /* Get the pending, enabled interrupts for the IN endpoint from the
2940	   * endpoint interrupt status register.
2941	   */
