3002	           * in the mask register, so we fake one here.
3003	           */
3004	
3005	          empty = esp32s3_getreg(ESP32S3_OTG_DIEPEMPMSK);
3006	          if ((empty & OTG_DIEPEMPMSK(epno)) != 0)
3007	            {
3008	              mask |= OTG_DIEPINT_TXFE;
3009	            }
3010	
3011	          /* Now, read the interrupt status and mask out all disabled
3012	           * interrupts.
3013	           */
3014	
3015	          diepint = esp32s3_getreg(ESP32S3_OTG_DIEPINT(epno)) & mask;
3016	
3017	          /* Decode and process the enabled, pending interrupts */
3018	
3019	          /* Transfer completed interrupt */
3020	
3021	          if ((diepint & OTG_DIEPINT_XFRC) != 0)
3022	            {
3023	              usbtrace(TRACE_INTDECODE(ESP32S3_TRACEINTID_EPIN_XFRC),
3024	                       (uint16_t)diepint);
3025	
3026	              /* It is possible that logic may be waiting for a the TxFIFO to
3027	               * become empty.  We disable the TxFIFO empty interrupt here;
3028	               * it will be re-enabled if there is still insufficient space
3029	               * in the TxFIFO.
3030	               */
3031	
3032	              empty &= ~OTG_DIEPEMPMSK(epno);
3033	              esp32s3_putreg(empty, ESP32S3_OTG_DIEPEMPMSK);
3034	              esp32s3_putreg(OTG_DIEPINT_XFRC, ESP32S3_OTG_DIEPINT(epno));
3035	
3036	              /* IN transfer complete */
3037	
3038	              esp32s3_epin(priv, epno);
3039	            }
3040	
3041	          /* Timeout condition */
3042	
3043	          if ((diepint & OTG_DIEPINT_TOC) != 0)
3044	            {
3045	              usbtrace(TRACE_INTDECODE(ESP32S3_TRACEINTID_EPIN_TOC),
3046	                       (uint16_t)diepint);
3047	              esp32s3_putreg(OTG_DIEPINT_TOC, ESP32S3_OTG_DIEPINT(epno));
3048	            }
3049	
3050	          /* IN token received when TxFIFO is empty.  Applies to non-periodic
3051	           * IN endpoints only.  This interrupt indicates that an IN token
3052	           * was received when the associated TxFIFO (periodic/non-periodic)
3053	           * was empty. This interrupt is asserted on the endpoint for which
3054	           * the IN token was received.
3055	           */
3056	
3057	          if ((diepint & OTG_DIEPINT_ITTXFE) != 0)
3058	            {
3059	              usbtrace(TRACE_INTDECODE(ESP32S3_TRACEINTID_EPIN_ITTXFE),
3060	                       (uint16_t)diepint);
