5162	      if ((regval & OTG_GRSTCTL_TXFFLSH) == 0)
5163	        {
5164	          break;
5165	        }
5166	    }
5167	
5168	  /* Wait for 3 PHY Clocks */
5169	
5170	  up_udelay(3);
5171	  return OK;
5172	}
