5151	 *
5152	 ****************************************************************************/
5153	
5154	static int esp32s3_txfifo_flush(uint32_t txfnum)
5155	{
5156	  uint32_t regval;
5157	  uint32_t timeout;
5158	
5159	  /* Initiate the TX FIFO flush operation */
5160	
5161	  regval = OTG_GRSTCTL_TXFFLSH | txfnum;
5162	  esp32s3_putreg(regval, ESP32S3_OTG_GRSTCTL);
5163	
5164	  /* Wait for the FLUSH to complete */
5165	
5166	  for (timeout = 0; timeout < ESP32S3_FLUSH_DELAY; timeout++)
5167	    {
5168	      regval = esp32s3_getreg(ESP32S3_OTG_GRSTCTL);
5169	      if ((regval & OTG_GRSTCTL_TXFFLSH) == 0)
5170	        {
5171	          break;
5172	        }
5173	    }
5174	
5175	  /* Wait for 3 PHY Clocks */
5176	
5177	  up_udelay(3);
5178	  return OK;
5179	}

