826	/****************************************************************************
827	 * Name: cdcncm_transmit_format
828	 *
829	 * Description:
830	 *   Format the data to be transmitted to the host in the format specified by
831	 *   the NCM protocol (Network Control Model) and the NCM NTB (Network
832	 *   Transfer Block) format.
833	 *
834	 * Input Parameters:
835	 *   self - Reference to the driver state structure
836	 *   pkt  - Reference to the packet to be transmitted
837	 *
838	 * Returned Value:
839	 *   None
840	 *
841	 ****************************************************************************/
842	
843	static void cdcncm_transmit_format(FAR struct cdcncm_driver_s *self,
844	                                   FAR netpkt_t *pkt)
845	{
846	  FAR const struct ndp_parser_opts_s *opts = self->parseropts;
847	  unsigned int dglen = netpkt_getdatalen(&self->dev, pkt);
848	  const int div = g_ntbparameters.ndpindivisor;
849	  const int rem = g_ntbparameters.ndpinpayloadremainder;
850	  const int dgramidxlen = 2 * opts->dgramitemlen;
851	  const int ndpalign = g_ntbparameters.ndpinalignment;
852	  FAR uint8_t *tmp;
853	  int ncblen;
854	  int ndpindex;
855	
856	  ncblen   = opts->nthsize;
857	  ndpindex = NCM_ALIGN(ncblen, ndpalign);
858	
859	  if (self->dgramcount == 0)
860	    {
861	      /* Fill NCB */
862	
863	      tmp = self->wrreq->buf;
864	      memset(tmp, 0, ncblen);
865	      cdcncm_put(&tmp, 4, opts->nthsign);
866	      cdcncm_put(&tmp, 2, opts->nthsize);
867	      tmp += 2;              /* Skip seq */
868	      tmp += opts->blocklen; /* Skip block len */
869	      cdcncm_put(&tmp, opts->ndpindex, ndpindex);
870	      self->dgramaddr = self->wrreq->buf + ndpindex +
871	                        opts->ndpsize + (TX_MAX_NUM_DPE + 1) * dgramidxlen;
872	      self->dgramaddr = (FAR uint8_t *)NCM_ALIGN((uintptr_t)self->dgramaddr,
873	                                                 div) + rem;
874	
875	      /* Fill NDP */
876	
877	      tmp = self->wrreq->buf + ndpindex;
878	      cdcncm_put(&tmp, 4, self->ndpsign);
879	      tmp += 2 + opts->reserved1;
880	      cdcncm_put(&tmp, opts->nextndpindex, 0);
881	    }
882	
883	  tmp = self->wrreq->buf + ndpindex + opts->ndpsize +
884	        self->dgramcount * dgramidxlen;
885	  cdcncm_put(&tmp, opts->dgramitemlen, self->dgramaddr - self->wrreq->buf);
886	  cdcncm_put(&tmp, opts->dgramitemlen, dglen);
887	
888	  /* Fill IP packet */
889	
890	  netpkt_copyout(&self->dev, self->dgramaddr, pkt, dglen, 0);
891	
892	  self->dgramaddr += dglen;
893	  self->dgramaddr  = (FAR uint8_t *)NCM_ALIGN((uintptr_t)self->dgramaddr,
894	                                              div) + rem;
895	
896	  self->dgramcount++;
897	}
