/****************************************************************************
 * Name: cdcncm_transmit_locked
 *
 * Description:
 *   Send the NTB built in txstage to the host.  If the previous NTB still
 *   holds the write request after CDCNCM_TXWAIT, it is cancelled: a write
 *   that never completes must not stop the network until a reboot.
 *
 * Input Parameters:
 *   self - Reference to the driver state structure
 *
 * Returned Value:
 *   None
 *
 * Assumptions:
 *   The caller holds txlock.
 *
 ****************************************************************************/

static void cdcncm_transmit_locked(FAR struct cdcncm_driver_s *self)
{
  static int nlogged;
  FAR const struct ndp_parser_opts_s *opts = self->parseropts;
  FAR uint8_t *tmp;
  const int dgramidxlen = 2 * opts->dgramitemlen;
  const int ndpalign = g_ntbparameters.ndpinalignment;
  int ncblen;
  int ndpindex;
  int totallen;
  int ret;

  /* Nothing to send, e.g. the delayed send after the NTB filled up */

  if (self->dgramcount == 0)
    {
      return;
    }

  /* Wait until the USB device request for Ethernet frame transmissions
   * becomes available.
   */

  ret = nxsem_tickwait_uninterruptible(&self->wrreq_idle, CDCNCM_TXWAIT);
  if (ret < 0)
    {
      /* Cancelling returns the request through cdcncm_wrcomplete() */

      EP_CANCEL(self->epbulkin, self->wrreq);
      ret = nxsem_tickwait_uninterruptible(&self->wrreq_idle,
                                           MSEC2TICK(100));
      if (nlogged < 3)
        {
          nlogged++;
          syslog(LOG_ERR, "cdcncm: TX stalled, NTB cancelled ret=%d busy=%d\n",
                 ret, self->txbusy);
        }

      /* Never queue the request twice.  If it is not queued, the count was
       * lost and sending without it puts the count right again.
       */

      if (ret < 0 && self->txbusy)
        {
          self->dgramcount = 0;
          return;
        }
    }

  ncblen   = opts->nthsize;
  ndpindex = NCM_ALIGN(ncblen, ndpalign);

  /* Fill NCB */

  tmp      = self->txstage + 8; /* Offset to block length */
  totallen = self->dgramaddr - self->txstage;
  cdcncm_put(&tmp, opts->blocklen, totallen);

  /* Fill NDP */

  tmp = self->txstage + ndpindex + 4; /* Offset to ndp length */
  cdcncm_put(&tmp, 2, opts->ndpsize + (self->dgramcount + 1) * dgramidxlen);

  tmp += opts->reserved1 + opts->nextndpindex + opts->reserved2 +
         self->dgramcount * dgramidxlen;
  self->dgramcount = 0;

  cdcncm_put(&tmp, opts->dgramitemlen, 0);
  cdcncm_put(&tmp, opts->dgramitemlen, 0);

  /* Send this half and build the next NTB in the other one.  The NULL
   * packet ends an NTB that is a multiple of the packet size, otherwise the
   * host takes the next NTB for the rest of this one.
   */

  self->wrreq->buf   = self->txstage;
  self->wrreq->len   = totallen;
  self->wrreq->flags = USBDEV_REQFLAGS_NULLPKT;
  self->txstage      = self->txstage == self->txmem ?
                       self->txmem + CDCNCM_TXHALF : self->txmem;

  self->txbusy = true;
  ret = EP_SUBMIT(self->epbulkin, self->wrreq);
  if (ret < 0)
    {
      self->txbusy = false;
      nxsem_post(&self->wrreq_idle);

      if (nlogged < 3)
        {
          nlogged++;
          syslog(LOG_ERR, "cdcncm: TX submit failed: %d\n", ret);
        }
    }
}

/****************************************************************************
 * Name: cdcncm_transmit_work
 *
 * Description:
 *   Send NTB to the USB device for ethernet frame transmission
 *
 * Input Parameters:
 *   arg - Reference to the driver state structure
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void cdcncm_transmit_work(FAR void *arg)
{
  FAR struct cdcncm_driver_s *self = arg;

  nxmutex_lock(&self->txlock);
  cdcncm_transmit_locked(self);
  nxmutex_unlock(&self->txlock);
}

