70	 /****************************************************************************
71	+ * Name: esp32s3_epin_abort
72	+ *
73	+ * Description:
74	+ *   Abort the transfer in progress on a non-EP0 IN endpoint and return
75	+ *   every queued request with -ESHUTDOWN.  Unlike esp32s3_epin_disable(),
76	+ *   the endpoint stays configured (USBAEP) and the next EP_SUBMIT() starts
77	+ *   a new transfer.  The endpoint registers are logged (the first few
78	+ *   times) because a write request that never completes is otherwise
79	+ *   invisible.
80	+ *
81	+ ****************************************************************************/
82	+
83	+static void esp32s3_epin_abort(struct esp32s3_ep_s *privep)
84	+{
85	+  static int nlogged;
86	+  struct esp32s3_req_s *privreq;
87	+  uint8_t epphy = privep->epphy;
88	+  irqstate_t flags;
89	+  uint32_t diepctl;
90	+  uint32_t diepint;
91	+  uint32_t dieptsiz;
92	+  uint32_t dtxfsts;
93	+  uint32_t empmsk;
94	+  uint32_t daintmsk;
95	+  uint32_t dsts;
96	+  size_t xfrd;
97	+  size_t len;
98	+  bool active;
99	+  int timeout = 0;
100	+
101	+  flags = enter_critical_section();
102	+
103	+  /* Nothing to abort if the last request already completed */
104	+
105	+  privreq = esp32s3_rqpeek(privep);
106	+  if (privreq == NULL)
107	+    {
108	+      leave_critical_section(flags);
109	+      return;
110	+    }
111	+
112	+  /* Snapshot the endpoint state before changing it */
113	+
114	+  diepctl  = esp32s3_getreg(ESP32S3_OTG_DIEPCTL(epphy));
115	+  diepint  = esp32s3_getreg(ESP32S3_OTG_DIEPINT(epphy));
116	+  dieptsiz = esp32s3_getreg(ESP32S3_OTG_DIEPTSIZ(epphy));
117	+  dtxfsts  = esp32s3_getreg(ESP32S3_OTG_DTXFSTS(epphy)) & OTG_DTXFSTS_MASK;
118	+  empmsk   = esp32s3_getreg(ESP32S3_OTG_DIEPEMPMSK);
119	+  daintmsk = esp32s3_getreg(ESP32S3_OTG_DAINTMSK);
120	+  dsts     = esp32s3_getreg(ESP32S3_OTG_DSTS);
121	+  active   = privep->active;
122	+  xfrd     = privreq->req.xfrd;
123	+  len      = privreq->req.len;
124	+
125	+  /* NAK further IN tokens.  If a transfer is armed, also disable the
126	+   * endpoint and wait (bounded, interrupts are off) for the core to
127	+   * confirm.  A late EPDISD is cleared by esp32s3_epin_interrupt().
128	+   */
129	+
130	+  if ((diepctl & OTG_DIEPCTL_EPENA) != 0)
131	+    {
132	+      esp32s3_putreg(diepctl | OTG_DIEPCTL_EPDIS | OTG_DIEPCTL_SNAK,
133	+                     ESP32S3_OTG_DIEPCTL(epphy));
134	+
135	+      while ((esp32s3_getreg(ESP32S3_OTG_DIEPINT(epphy)) &
136	+              OTG_DIEPINT_EPDISD) == 0 && ++timeout < 1000)
137	+        {
138	+          up_udelay(1);
139	+        }
140	+    }
141	+  else
142	+    {
143	+      esp32s3_putreg(diepctl | OTG_DIEPCTL_SNAK,
144	+                     ESP32S3_OTG_DIEPCTL(epphy));
145	+    }
146	+
147	+  /* Drop whatever is left in the TxFIFO, stop waiting for it to drain and
148	+   * clear the stale interrupt flags.
149	+   */
150	+
151	+  esp32s3_txfifo_flush(OTG_GRSTCTL_TXFNUM_D(epphy));
152	+  esp32s3_putreg(empmsk & ~OTG_DIEPEMPMSK(epphy), ESP32S3_OTG_DIEPEMPMSK);
153	+  esp32s3_putreg(OTG_DIEPINT_XFRC | OTG_DIEPINT_EPDISD | OTG_DIEPINT_TOC |
154	+                 OTG_DIEPINT_ITTXFE | OTG_DIEPINT_INEPNE,
155	+                 ESP32S3_OTG_DIEPINT(epphy));
156	+
157	+  /* Nothing is in flight any more, so the next submit starts a transfer */
158	+
159	+  privep->active = false;
160	+  privep->zlp    = false;
161	+  esp32s3_req_cancel(privep, -ESHUTDOWN);
162	+  leave_critical_section(flags);
163	+
164	+  if (nlogged < 3)
165	+    {
166	+      nlogged++;
167	+      syslog(LOG_ERR, "otg: EP%d abort ctl=%08" PRIx32 " int=%" PRIx32
168	+             " tsiz=%08" PRIx32 " fifo=%" PRIu32 " emp=%" PRIx32
169	+             " msk=%" PRIx32 " dsts=%" PRIx32 " act=%d %zu/%zu t=%d\n",
170	+             epphy, diepctl, diepint, dieptsiz, dtxfsts, empmsk, daintmsk,
171	+             dsts, active, xfrd, len, timeout);
172	+    }
173	+}
