input.content:
import json, sys

# Print the last N assistant/tool texts containing a needle, with context.
sys.stdout.reconfigure(encoding="utf-8")
path, needle, n, ctx = sys.argv[1], sys.argv[2], int(sys.argv[3]), int(sys.argv[4])
hits = []


def texts(content):
    if isinstance(content, str):
        yield content
    elif isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                continue
            if c.get("type") == "text":
                yield c.get("text", "")
            elif c.get("type") == "tool_use":
                yield json.dumps(c.get("input", {}), ensure_ascii=False)
            elif c.get("type") == "tool_result":
                yield from texts(c.get("content"))


with open(path, encoding="utf-8", errors="replace") as f:
    for lineno, line in enumerate(f, 1):
        if needle not in line:
            continue
        try:
            ev = json.loads(line)
        except ValueError:
            continue
        role = ev.get("type")
        for t in texts(ev.get("message", {}).get("content")):
            i = t.find(needle)
            while i >= 0:
                hits.append((lineno, role, ev.get("timestamp", ""),
                             t[max(0, i - ctx):i + len(needle) + ctx]))
                i = t.find(needle, i + 1)

for lineno, role, ts, s in hits[-n:]:
    print("=" * 20, lineno, role, ts)
    print(s)

