import glob, json, os, sys
from collections import Counter

# Read-only: report seq coverage of one session's contest log slices across
# all day folders, plus the manifest's event_count for that session.
root, sid = sys.argv[1], sys.argv[2]


def ranges(nums):
    out, start, prev = [], None, None
    for n in nums:
        if start is None:
            start = prev = n
        elif n == prev + 1:
            prev = n
        else:
            out.append((start, prev))
            start = prev = n
    if start is not None:
        out.append((start, prev))
    return out


files = sorted(glob.glob(os.path.join(root, "*", f"claude-code__{sid}.jsonl")))
allseq = Counter()
for f in files:
    seqs, bad = [], 0
    with open(f, "rb") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                seqs.append(int(json.loads(line)["seq"]))
            except Exception:
                bad += 1
    allseq.update(seqs)
    rng = f"{min(seqs)}..{max(seqs)}" if seqs else "-"
    print(f"{os.path.relpath(f, root)}  lines={len(seqs)}  seq={rng}"
          f"  unparsed={bad}  bytes={os.path.getsize(f)}")

if allseq:
    top = max(allseq)
    missing = [s for s in range(top + 1) if s not in allseq]
    dups = sum(c - 1 for c in allseq.values() if c > 1)
    print(f"TOTAL files={len(files)} unique_seq={len(allseq)} max_seq={top}"
          f" missing={len(missing)} dup_lines={dups}")
    if missing:
        print("missing ranges (first 10):", ranges(missing)[:10])
else:
    print("TOTAL no slices found")

man = os.path.join(root, "manifest.json")
if os.path.exists(man):
    with open(man, encoding="utf-8") as fh:
        m = json.load(fh)
    entries = m.get("sessions", m) if isinstance(m, dict) else m
    hit = None
    if isinstance(entries, list):
        hit = [e for e in entries if isinstance(e, dict) and sid in str(e.get("session_id", ""))]
    elif isinstance(entries, dict):
        hit = [v for k, v in entries.items() if sid in k]
    for e in hit or []:
        if isinstance(e, dict):
            print("manifest:", {k: e.get(k) for k in ("event_count", "file", "path", "last_seq") if k in e})
        else:
            print("manifest:", e)
    if not hit:
        print("manifest: no entry for this session (top-level keys:",
              list(m.keys())[:10] if isinstance(m, dict) else type(m).__name__, ")")
